<!-- Pedido sugerido 2026 (gzip+base64): cliente -> {codigo: piezas} -->
<script id="SUGERIDO_B64" type="text/plain"></script>

<!-- Compra 2025 (gzip+base64): cliente -> {codigo: unidades2025} -->
<script id="COMPRA2025_B64" type="text/plain"></script>
<script id="CON2025_B64" type="text/plain"></script>

<script>/* ============================================================================
   Padcolor Pre-Pedidos v8 - Aplicación principal
   ============================================================================ */
(function(){
'use strict';

// ===== Carga de datos =====
const DATA = JSON.parse(document.getElementById('DATA_JSON').textContent);
const PRODUCTS = DATA.products;

// ===== Pedido sugerido 2026 (embebido, gzip+base64) =====
// Estructura: { "CLI-N": { "codigoUPC": piezasSugeridas, ... }, ... }
// Se descomprime de forma perezosa con DecompressionStream('gzip').
let SUGERIDO = null;          // cache una vez descomprimido
let SUGERIDO_LOADING = null;  // promesa en curso
async function cargarSugerido(){
  if(SUGERIDO) return SUGERIDO;
  if(SUGERIDO_LOADING) return SUGERIDO_LOADING;
  SUGERIDO_LOADING = (async () => {
    const b64 = (document.getElementById('SUGERIDO_B64')?.textContent || '').trim();
    if(!b64) return (SUGERIDO = {});
    const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
    let jsonText;
    if(typeof DecompressionStream !== 'undefined'){
      const ds = new DecompressionStream('gzip');
      const stream = new Blob([bytes]).stream().pipeThrough(ds);
      jsonText = await new Response(stream).text();
    } else {
      throw new Error('DecompressionStream no soportado en este navegador');
    }
    SUGERIDO = JSON.parse(jsonText);
    return SUGERIDO;
  })();
  return SUGERIDO_LOADING;
}

// ===== Compra 2025 por cliente (embebida, gzip+base64) =====
// Estructura: { "CLI-N": { "codigoUPC": unidades2025, ... }, ... }
// Se precarga al iniciar para mostrar la columna "Pz 2025" en la revisión
// de forma síncrona (sin await por renglón).
let COMPRA2025 = null;
async function cargarCompra2025(){
  if(COMPRA2025) return COMPRA2025;
  const b64 = (document.getElementById('COMPRA2025_B64')?.textContent || '').trim();
  if(!b64) return (COMPRA2025 = {});
  try {
    const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
    if(typeof DecompressionStream !== 'undefined'){
      const ds = new DecompressionStream('gzip');
      const stream = new Blob([bytes]).stream().pipeThrough(ds);
      COMPRA2025 = JSON.parse(await new Response(stream).text());
    } else {
      COMPRA2025 = {};
    }
  } catch(e){
    console.error('No se pudo cargar compra 2025:', e);
    COMPRA2025 = {};
  }
  return COMPRA2025;
}
// Set de números de cliente (mayúsculas) con compra en 2025 (col B del XLSB
// de metas). Solo estos clientes activan el botón "Ver sugerido".
let CON2025 = null;
// Candado: número de cliente para el que ya se aplicó el sugerido embebido.
// Evita que clics repetidos en "Ver sugerido" dupliquen el pedido.
let sugeridoAplicadoPara = null;
async function cargarCon2025(){
  if(CON2025) return CON2025;
  const b64 = (document.getElementById('CON2025_B64')?.textContent || '').trim();
  CON2025 = new Set();
  if(!b64) return CON2025;
  try {
    const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
    if(typeof DecompressionStream !== 'undefined'){
      const ds = new DecompressionStream('gzip');
      const stream = new Blob([bytes]).stream().pipeThrough(ds);
      const arr = JSON.parse(await new Response(stream).text());
      CON2025 = new Set(arr.map(n => String(n).toUpperCase()));
    }
  } catch(e){
    console.error('No se pudo cargar lista compra 2025:', e);
  }
  // Re-evalúa el botón por si el cliente ya estaba capturado al cargar.
  actualizarHeaderSugerido();
  return CON2025;
}
// Consulta síncrona: ¿el cliente tuvo compra en 2025?
function tieneCompra2025(cli){
  if(!cli || cli._comodin || !CON2025) return false;
  return CON2025.has(String(cli.n).toUpperCase());
}
// Consulta síncrona: unidades 2025 de un código para el cliente actual (0 si no hay).
function pz2025De(codigo){
  const cli = state.cliente;
  if(!cli || cli._comodin || !COMPRA2025) return 0;
  const m = COMPRA2025[String(cli.n).toUpperCase()];
  return (m && m[codigo]) ? m[codigo] : 0;
}
// Orden estable global: por página del catálogo ASC, luego por código UPC.
// Productos sin página quedan al final.
PRODUCTS.sort((a, b) => {
  const pa = a.p || 99999;
  const pb = b.p || 99999;
  if (pa !== pb) return pa - pb;
  return (a.c || '').localeCompare(b.c || '');
});
const CLIENTS = DATA.clients;
const AGENTS = DATA.agents;
const CATEGORIES = DATA.categories;
const GRUPOS = DATA.grupos;

// Imágenes del catálogo (página impresa → dataURL JPEG base64).
// El elemento puede no existir si el HTML se sirvió sin imágenes.
const IMAGES = (function(){
  const el = document.getElementById('IMAGES_JSON');
  if(!el) return {};
  try { return JSON.parse(el.textContent); }
  catch(e){ console.warn('IMAGES_JSON parse failed', e); return {}; }
})();

// ===== Mapas de búsqueda rápida =====
const CLIENTS_BY_NUM = {};
CLIENTS.forEach(c => CLIENTS_BY_NUM[c.n.toUpperCase()] = c);
const AGENTS_BY_NAME = {};
AGENTS.forEach(a => AGENTS_BY_NAME[a.nom.toUpperCase()] = a);

// Mapa entidad -> almacenes (para referencia, ya viene calculado por entidad)
const PRICE_LIST_INDEX = {'LISTA':0,'A':1,'B':2,'C':3};

// ===== Estado global =====
const state = {
  cliente: null,           // objeto cliente o sentinel { x: 'COMODIN' } para XXXXX
  agente: null,            // objeto agente
  entidad: 'TGR',          // C2 o TGR según el agente
  priceIdx: 0,             // 0=Lista, 1=A, 2=B, 3=C
  carrito: {},             // {codigo: {p: <product>, q: <paquetes>}}
  search: '',
  filterEspecial: false,
  filterNuevos: false,
  filterGrupo: '',
  filterPage: '',
  showLimit: 60,           // virtualización ligera: solo render N a la vez
  tipoPersona: 'moral',    // 'moral' o 'fisica' — afecta pagaré y adjunto del poder
};

// ===== Helpers =====
const $ = (id) => document.getElementById(id);
const fmt = (n) => '$' + (Number(n)||0).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});
const fmtInt = (n) => (Number(n)||0).toLocaleString('es-MX');

function toast(msg, type='info', ms=3000){
  const t = document.createElement('div');
  t.className = 'toast' + (type==='success'?' success':type==='error'?' error':'');
  t.textContent = msg;
  $('toast-area').appendChild(t);
  setTimeout(()=>t.remove(), ms);
}

function showModal(title, bodyHTML, footerHTML, opts){
  opts = opts || {};
  $('modal-title').textContent = title;
  $('modal-body').innerHTML = bodyHTML;
  const mc = $('modal-content');
  mc.classList.toggle('modal-wide', !!opts.wide);
  if(footerHTML === null){
    $('modal-footer').style.display = 'none';
  } else {
    $('modal-footer').style.display = '';
    if(footerHTML !== undefined){
      $('modal-footer').innerHTML = footerHTML;
    } else {
      $('modal-footer').innerHTML = '<button class="filter-toggle" data-close>Cerrar</button>';
    }
  }
  $('modal').classList.add('show');
}
function closeModal(){ $('modal').classList.remove('show'); }
$('modal').addEventListener('click', e => {
  if(e.target.id==='modal' || e.target.dataset.close !== undefined) closeModal();
});

// ===== Cliente: validación =====
function validarCliente(num){
  const upper = (num||'').trim().toUpperCase();
  if(!upper){ state.cliente = null; sugeridoAplicadoPara = null; resetClienteUI(); renderProductos(); actualizarFinalizar(); return; }

  // Cliente comodín
  if(upper === 'XXXXX'){
    state.cliente = { _comodin: true, n: 'XXXXX', rs:'', nc:'', rfc:'', lc:0, sa:0, pl:'Lista', plz:30, dom:'' };
    state.priceIdx = 0;
    state.entidad = 'TGR';
    state.agente = { nom:'Asistente de Ventas', mail:'auxventas@padcolor.com', wa:'', ent:'TGR' };
    aplicarClienteUI();
    setMsg('cli-msg', 'Cliente comodín XXXXX activo. Lista de precios: Lista. Sin crédito. El pedido irá al asistente de ventas. Captura RFC para continuar.', 'success');
    $('cli-num').classList.add('success');
    $('cli-num').classList.remove('error');
    bloquearForm(false);
    actualizarFinalizar();
    renderProductos();
    return;
  }

  const cli = CLIENTS_BY_NUM[upper];
  if(!cli){
    state.cliente = null;
    state.agente = null;
    setMsg('cli-msg', 'No existe. Intentar de nuevo.', 'error');
    $('cli-num').classList.add('error');
    $('cli-num').classList.remove('success');
    resetClienteUI();
    bloquearForm(true);
    renderProductos();
    return;
  }
  if(cli.bl === 'Checked'){
    state.cliente = null;
    state.agente = null;
    setMsg('cli-msg', 'Cliente con bloqueo administrativo. Contacta a tu ejecutivo.', 'error');
    $('cli-num').classList.add('error');
    $('cli-num').classList.remove('success');
    resetClienteUI();
    bloquearForm(true);
    renderProductos();
    return;
  }
  // Cliente OK
  state.cliente = cli;
  sugeridoAplicadoPara = null;
  const plKey = (cli.pl||'Lista').toUpperCase();
  state.priceIdx = PRICE_LIST_INDEX[plKey] !== undefined ? PRICE_LIST_INDEX[plKey] : 0;
  state.agente = AGENTS_BY_NAME[(cli.ag||'').toUpperCase()] || null;
  state.entidad = state.agente ? state.agente.ent : 'TGR';

  aplicarClienteUI();
  setMsg('cli-msg', '', '');
  $('cli-num').classList.add('success');
  $('cli-num').classList.remove('error');
  bloquearForm(false);
  actualizarFinalizar();
  renderProductos();
}

// ===== Helpers de formato =====
function formatWhatsApp(raw){
  // Acepta cualquier formato, extrae dígitos y formatea como (XX)XXXX-XXXX
  if(!raw) return '';
  const d = String(raw).replace(/\D/g,'');
  if(d.length === 10) return `(${d.slice(0,2)})${d.slice(2,6)}-${d.slice(6,10)}`;
  return raw; // si no son 10 dígitos, devolver como vino
}
function setMsg(id, msg, type){
  const el = $(id);
  el.textContent = msg;
  el.className = 'form-msg' + (msg ? ' show ' + (type||'') : '');
}
function resetClienteUI(){
  $('cli-rs').value = '';
  $('cli-rfc').value = '';
  // Sucursal es captura libre y debe limpiarse aquí (cuando se está
  // cambiando o quitando el cliente). En `nuevoPedido()`, en cambio, se
  // CONSERVA porque el mismo cliente captura otro pedido.
  if($('cli-sucursal')) $('cli-sucursal').value = '';
  // cli-lc / cli-disp viven dentro del bloque amarillo de exceso de crédito,
  // que se llena y muestra solo cuando el total del pedido excede el límite.
  $('ag-nombre').textContent = 'Captura tu núm. de cliente';
  $('ag-nombre').classList.add('ag-empty');
  $('ag-wa').textContent = '—';
  $('ag-wa').classList.add('ag-empty');
  $('ag-mail').textContent = '—';
  $('ag-mail').classList.add('ag-empty');
  const pcb = $('promo-client-banner');
  if(pcb){ pcb.style.display = 'none'; pcb.innerHTML = ''; }
}
function aplicarClienteUI(){
  const cli = state.cliente;
  // Razón Social = columna B del catálogo de clientes (cli.rs). Si no existe,
  // hacemos fallback al nombre comercial (cli.nc) para no dejar el campo vacío.
  $('cli-rs').value = cli.rs || cli.nc || '';
  // NO auto-completar el RFC: el cliente DEBE capturarlo y debe coincidir
  // con el del catálogo (validación de seguridad).
  $('cli-rfc').value = '';
  validarRfc();
  // cli-lc / cli-disp se actualizan en renderCarrito sólo cuando el bloque
  // amarillo de exceso de crédito está visible. No se llenan acá.
  if(state.agente){
    $('ag-nombre').textContent = state.agente.nom;
    $('ag-nombre').classList.remove('ag-empty');
    const waFmt = formatWhatsApp(state.agente.wa);
    $('ag-wa').textContent = waFmt || '—';
    $('ag-wa').classList.toggle('ag-empty', !waFmt);
    $('ag-mail').textContent = state.agente.mail || '—';
    $('ag-mail').classList.toggle('ag-empty', !state.agente.mail);
  }
  renderPromoClientBanner();
}
function bloquearForm(bloq){
  ['cli-email','cli-tel','cli-rfc','cli-sucursal'].forEach(id => {
    const el = $(id);
    if(el) el.disabled = bloq;
  });
  $('btn-finalize').disabled = bloq;
}

// ===== Inventario por entidad del cliente =====
function getStock(prod){
  if(!state.cliente) return prod.qC + prod.qT; // antes de validar, suma de ambas
  return state.entidad === 'C2' ? prod.qC : prod.qT;
}
function getStockPiezas(prod){
  if(!state.cliente) return prod.iC + prod.iT;
  return state.entidad === 'C2' ? prod.iC : prod.iT;
}

// ===== Precios =====
function getPrecioPieza(prod){
  return prod.pp[state.priceIdx] || 0;
}
function getPrecioPaquete(prod){
  // Si trae el precio múltiplo lo usa; si no, calcula precio_pieza × multiplo
  const pq = prod.pq[state.priceIdx];
  if(pq && pq > 0) return pq;
  return getPrecioPieza(prod) * prod.m;
}
function tienePrecio(prod){
  return getPrecioPieza(prod) > 0 || getPrecioPaquete(prod) > 0;
}

// ===== Filtrado =====
let _filteredCache = null;
function filterProducts(){
  const q = state.search.trim().toLowerCase();
  const qDigits = q.replace(/\D/g,'');
  const onlyEsp = state.filterEspecial;
  const onlyNuevos = state.filterNuevos;
  const grp = state.filterGrupo;
  const pag = state.filterPage;

  const result = PRODUCTS.filter(p => {
    if(onlyEsp && !p.e) return false;
    if(onlyNuevos && !p.n) return false;
    if(grp && p.g !== grp) return false;
    if(pag && String(p.p||'') !== pag) return false;
    if(q){
      const hay = (p.d||'').toLowerCase();
      const cod = (p.c||'').toLowerCase();
      const cp = (p.cp||'').toLowerCase();
      const u5 = (p.u5||'').toLowerCase();
      const sr = (p.sr||'').toLowerCase();
      const tm = (p.tm||'').toLowerCase();
      const cat = (p.cat||'').toLowerCase();
      // Match: cualquier término de búsqueda en cualquier campo
      const terms = q.split(/\s+/).filter(Boolean);
      for(const t of terms){
        const tDigits = t.replace(/\D/g,'');
        const inText = hay.includes(t) || cat.includes(t) || sr.includes(t) || tm.includes(t);
        const inCode = (cod.includes(t) || (tDigits && (cod.includes(tDigits) || cp.includes(tDigits) || u5.includes(tDigits))));
        if(!inText && !inCode) return false;
      }
    }
    return true;
  });
  _filteredCache = result;
  return result;
}

// ===== Render productos =====
// ===== Helper: cliente listo para mostrar catálogo =====
// El catálogo (productos + precios) y el carrito sólo se habilitan cuando:
// (a) hay un cliente validado, y
// (b) el RFC capturado pasa la validación (formato + coincidencia con catálogo).
function clienteListo(){
  if(!state.cliente) return false;
  const v = ($('cli-rfc').value || '').toUpperCase().trim();
  const formatoOk = /^[A-ZÑ&]{3,4}\d{6}[A-Z\d]{3}$/.test(v);
  if(!formatoOk) return false;
  if(state.cliente._comodin) return true;
  const rfcCat = (state.cliente.rfc || '').toUpperCase().trim();
  // Si el cliente no tiene RFC registrado, aceptar cualquier RFC con formato válido
  if(!rfcCat) return true;
  return v === rfcCat;
}

function renderProductos(){
  // Actualizar banner de lista de precios
  const banner = $('price-list-banner');
  const bannerText = $('price-list-banner-text');
  if(banner && bannerText){
    const listas = ['Lista', 'A', 'B', 'C'];
    const listaActual = listas[state.priceIdx] || 'Lista';
    if(clienteListo()){
      const cliNum = state.cliente._comodin ? 'XXXXX' : state.cliente.n;
      bannerText.innerHTML = `Mostrando precios <strong>${listaActual}</strong> para cliente <strong>${cliNum}</strong>.`;
      banner.classList.add('ready');
    } else {
      bannerText.innerHTML = `Mostrando precios <strong>Lista</strong>. Captura tu número de cliente y RFC para ver tus precios y habilitar el carrito.`;
      banner.classList.remove('ready');
    }
  }

  const filtered = filterProducts();
  const total = PRODUCTS.length;
  $('count-shown').textContent = filtered.length;
  $('count-total').textContent = total;

  // Mostrar/ocultar reset
  const anyFilter = state.search || state.filterEspecial || state.filterNuevos ||
                    state.filterGrupo || state.filterPage;
  $('reset-filters').style.display = anyFilter ? 'inline-flex' : 'none';

  const grid = $('products-grid');
  const empty = $('empty-state');
  const loadMore = $('load-more');

  if(filtered.length === 0){
    grid.innerHTML = '';
    empty.innerHTML = 'No se encontraron productos con los filtros actuales.';
    empty.style.display = 'block';
    loadMore.style.display = 'none';
    return;
  }
  empty.style.display = 'none';

  // Render hasta showLimit
  const visible = filtered.slice(0, state.showLimit);
  grid.innerHTML = visible.map(p => productCardHTML(p)).join('');
  
  loadMore.style.display = filtered.length > state.showLimit ? 'block' : 'none';

  // Wire-up event listeners en cards
  grid.querySelectorAll('[data-add]').forEach(b => {
    b.addEventListener('click', () => addAlCarrito(b.dataset.add));
  });
  grid.querySelectorAll('[data-qmin]').forEach(b => {
    b.addEventListener('click', () => adjustQty(b.dataset.qmin, -1));
  });
  grid.querySelectorAll('[data-qplus]').forEach(b => {
    b.addEventListener('click', () => adjustQty(b.dataset.qplus, +1));
  });
  grid.querySelectorAll('[data-qty]').forEach(inp => {
    inp.addEventListener('input', e => onQtyInput(inp.dataset.qty, e.target));
    inp.addEventListener('blur', e => clampQty(inp.dataset.qty, e.target));
  });
  grid.querySelectorAll('[data-modelo]').forEach(b => {
    b.addEventListener('click', () => abrirModeloDetalle(b.dataset.modelo));
  });
}

function productCardHTML(p){
  const stock = getStock(p);
  const stockPz = getStockPiezas(p);
  const agotado = stock <= 0;
  const precioPz = getPrecioPieza(p);
  const precioPq = getPrecioPaquete(p);
  const sinPrecio = !tienePrecio(p);
  const inCart = state.carrito[p.c];
  const qty = inCart ? inCart.q : 0;
  const max = stock;

  // Imagen / placeholder
  let imgHTML = '';
  if(p.p){
    const src = IMAGES[p.p];
    if(src){
      imgHTML = `<div class="product-img has-img" data-page="${p.p}" data-modelo="${p.c}" title="Click para ampliar página ${p.p} del catálogo">
        <img src="${src}" alt="Página ${p.p}" loading="lazy">
        <span class="product-img-page">Pág ${p.p}</span>`;
    } else {
      imgHTML = `<div class="product-img" data-modelo="${p.c}" title="Página ${p.p} del catálogo">
        <span style="font-size:11px;color:var(--pad-grey-500);font-weight:600">📄 Página ${p.p}</span>
        <span class="product-img-page">Pág ${p.p}</span>`;
    }
    if(p.cp && p.pe){
      imgHTML += `<span class="product-img-modelo" title="Modelo en el PDF">#${p.cp}</span>`;
    }
    if(p.e) imgHTML += `<span class="product-tag-e">$E</span>`;
    if(p.n) imgHTML += `<span class="product-tag-nuevo">¡Nuevo!</span>`;
    imgHTML += `</div>`;
  } else {
    imgHTML = `<div class="product-img no-img">
      <span>Imagen no disponible</span>`;
    if(p.cp && p.pe){
      imgHTML += `<span class="product-img-modelo">#${p.cp}</span>`;
    }
    if(p.e) imgHTML += `<span class="product-tag-e">$E</span>`;
    if(p.n) imgHTML += `<span class="product-tag-nuevo">¡Nuevo!</span>`;
    imgHTML += `</div>`;
  }

  // Precios
  let priceHTML;
  if(sinPrecio){
    priceHTML = `<div class="price-noprice">Producto sin precio</div>`;
  } else {
    priceHTML = `
      <div class="price-block">
        <span class="price-label">Pieza</span>
        <span class="price-value">${fmt(precioPz)}</span>
      </div>
      <div class="price-block" style="text-align:right">
        <span class="price-label">Paquete</span>
        <span class="price-value price-paq">${fmt(precioPq)}</span>
      </div>`;
  }

  // Acciones
  const listo = clienteListo();
  const dis = agotado ? 'disabled' : '';
  const minDis = (qty<=0) ? 'disabled' : '';
  const plusDis = (qty>=max) ? 'disabled' : '';
  const addDis = (agotado || !listo) ? 'disabled' : '';
  const addTip = !listo ? 'title="Captura núm. de cliente y RFC para agregar al carrito"' : '';
  const addText = !listo ? '🔒 Agregar' : 'Agregar';
  const actionsHTML = agotado ? '' : `
    <div class="qty-label" style="margin-top:6px">Paquetes</div>
    <div class="product-actions">
      <div class="qty-input-wrap">
        <button class="qty-btn" data-qmin="${p.c}" ${minDis}>−</button>
        <input class="qty-input" type="number" min="0" max="${max}" value="${qty}" data-qty="${p.c}">
        <button class="qty-btn" data-qplus="${p.c}" ${plusDis}>+</button>
      </div>
      <button class="btn-add" data-add="${p.c}" ${addDis} ${addTip}>${addText}</button>
    </div>
    <div class="qty-max-hint">Máx: ${fmtInt(max)} paquetes (${fmtInt(stockPz)} pz)</div>`;

  // Stock label
  const stockClass = agotado ? 'out' : 'in';
  const stockText = agotado ? 'Agotado' : `${fmtInt(stock)} paquetes disponibles`;

  return `<div class="product-card${agotado?' agotado':''}">
    ${imgHTML}
    <div class="product-body">
      <span class="product-code">${p.c}${p.cp&&p.pe?' · #'+p.cp:''}</span>
      <span class="product-desc" title="${p.d.replace(/"/g,'&quot;')}">${p.d}</span>
      <span class="product-pack">📦 Unidad de venta: paq c/${p.m} pz</span>
      <span class="product-stock ${stockClass}">
        ${agotado?'⊘':'✓'} ${stockText}
      </span>
      <div class="product-prices">
        ${priceHTML}
      </div>
      ${actionsHTML}
    </div>
  </div>`;
}

function abrirModeloDetalle(codigo){
  const p = PRODUCTS.find(x => x.c === codigo);
  if(!p || !p.p) return;
  const src = IMAGES[p.p];
  const imgBlock = src
    ? `<div style="text-align:center;margin-bottom:14px">
         <img src="${src}" alt="Página ${p.p}" style="max-width:100%;max-height:70vh;border-radius:8px;box-shadow:0 4px 20px rgba(0,0,0,.15)">
       </div>`
    : `<div style="background:var(--pad-grey-100);padding:80px 20px;border-radius:8px;margin-bottom:14px;text-align:center">
         <div style="font-size:48px;color:var(--pad-grey-300)">📄</div>
         <div style="font-size:14px;color:var(--pad-grey-500);margin-top:10px">Imagen de la página ${p.p} del catálogo (no disponible)</div>
       </div>`;
  const body = `
    ${imgBlock}
    <h3 style="margin-bottom:8px">${p.d}</h3>
    <div style="font-size:12.5px;color:var(--pad-grey-700);line-height:1.7">
      <strong>Código UPC-A:</strong> ${p.c}<br>
      ${p.cp ? `<strong>Modelo (código en PDF):</strong> ${p.cp}<br>` : ''}
      ${p.u5 ? `<strong>Código central UPC (5 dígitos):</strong> ${p.u5}<br>` : ''}
      <strong>Página catálogo:</strong> ${p.p}<br>
      <strong>Categoría:</strong> ${p.cat}<br>
      ${p.sr ? `<strong>Serie:</strong> ${p.sr} · <strong>Tamaño:</strong> ${p.tm||'—'}<br>`:''}
    </div>`;
  showModal(`Producto del catálogo Día de Muertos · Halloween 2026`, body);
}

// ===== Carrito =====
function addAlCarrito(codigo){
  if(!clienteListo()){ toast('Captura cliente y RFC para hacer pedido', 'error'); return; }
  const p = PRODUCTS.find(x => x.c === codigo);
  if(!p) return;
  const inputEl = document.querySelector(`[data-qty="${codigo}"]`);
  let qty = parseInt(inputEl?.value || '0', 10) || 0;
  if(qty <= 0) qty = 1;
  const max = getStock(p);
  if(qty > max) qty = max;
  if(qty <= 0){ toast('Sin existencia', 'error'); return; }

  state.carrito[codigo] = { p, q: qty };
  toast(`✓ Agregado: ${qty} paq de ${p.d.substring(0,40)}`, 'success', 1800);
  renderCarrito();
  actualizarFinalizar();
  renderProductos();
}
function adjustQty(codigo, delta){
  const p = PRODUCTS.find(x => x.c === codigo);
  if(!p) return;
  const inputEl = document.querySelector(`[data-qty="${codigo}"]`);
  if(!inputEl) return;
  let v = parseInt(inputEl.value || '0', 10) || 0;
  v += delta;
  const max = getStock(p);
  if(v < 0) v = 0;
  if(v > max) v = max;
  inputEl.value = v;
  // Actualizar estado de botones
  const minBtn = document.querySelector(`[data-qmin="${codigo}"]`);
  const plusBtn = document.querySelector(`[data-qplus="${codigo}"]`);
  if(minBtn) minBtn.disabled = v <= 0;
  if(plusBtn) plusBtn.disabled = v >= max;
}
function onQtyInput(codigo, input){
  const p = PRODUCTS.find(x => x.c === codigo);
  if(!p) return;
  let v = parseInt(input.value||'0',10);
  if(isNaN(v) || v < 0) v = 0;
  const max = getStock(p);
  if(v > max){ v = max; toast(`Máx ${max} paquetes disponibles`, 'error', 1500); }
  input.value = v;
}
function clampQty(codigo, input){
  let v = parseInt(input.value||'0',10);
  if(isNaN(v) || v < 0) input.value = 0;
}
function eliminarDelCarrito(codigo){
  delete state.carrito[codigo];
  renderCarrito();
  actualizarFinalizar();
  renderProductos();
}
function cambiarQtyCarrito(codigo, qty){
  const it = state.carrito[codigo];
  if(!it) return;
  const max = getStock(it.p);
  let v = parseInt(qty,10) || 0;
  if(v <= 0){ eliminarDelCarrito(codigo); return; }
  if(v > max) v = max;
  it.q = v;
  renderCarrito();
  actualizarFinalizar();
  renderProductos();
}

// ===== Pedido sugerido: aplicar líneas al carrito =====
// lineas: array de { codigo, piezas }. Cruza con PRODUCTS, respeta existencia,
// fusiona con lo que ya esté en el carrito (suma cantidades), reporta resultado.
function aplicarSugeridoLineas(lineas){
  if(!clienteListo()){ toast('Captura cliente y RFC antes de cargar un sugerido', 'error'); return; }
  let agregados = 0, fusionados = 0, sinProducto = 0, agotados = 0, recortados = 0;
  lineas.forEach(({codigo, piezas}) => {
    const cod = String(codigo).trim();
    let pz = parseInt(piezas, 10) || 0;
    if(pz <= 0) return;
    const p = PRODUCTS.find(x => String(x.c) === cod);
    if(!p){ sinProducto++; return; }
    const max = getStock(p);
    if(max <= 0){ agotados++; return; }
    const existente = state.carrito[cod];
    let destino = (existente ? existente.q : 0) + pz;
    if(destino > max){ destino = max; recortados++; }
    if(existente){ existente.q = destino; fusionados++; }
    else { state.carrito[cod] = { p, q: destino }; agregados++; }
  });
  renderCarrito();
  actualizarFinalizar();
  renderProductos();
  const partes = [];
  if(agregados) partes.push(`${agregados} agregado(s)`);
  if(fusionados) partes.push(`${fusionados} sumado(s) a lo existente`);
  if(recortados) partes.push(`${recortados} recortado(s) por existencia`);
  if(agotados) partes.push(`${agotados} sin existencia`);
  if(sinProducto) partes.push(`${sinProducto} no encontrado(s) en catálogo`);
  if(agregados + fusionados === 0){
    toast(partes.length ? `Nada se agregó: ${partes.join(', ')}` : 'No había líneas válidas en el sugerido', 'error', 4000);
  } else {
    toast(`✓ Sugerido cargado: ${partes.join(', ')}`, 'success', 4000);
  }
}

// Habilita/inhabilita el control de pedido sugerido del header según el
// estado del cliente, y actualiza el texto de ayuda. El sugerido aplica
// solo a clientes registrados (no comodín XXXXX) y con RFC validado.
function actualizarHeaderSugerido(){
  const btn = $('btn-sugerido');
  const hint = $('hs-hint');
  if(!btn) return;
  const cli = state.cliente;
  const listo = clienteListo();
  const con2025 = tieneCompra2025(cli);
  const yaAplicado = cli && !cli._comodin && sugeridoAplicadoPara === String(cli.n).toUpperCase();
  const aplica = listo && cli && !cli._comodin && con2025 && !yaAplicado;
  btn.disabled = !aplica;
  if(yaAplicado){ btn.textContent = '✓ Sugerido agregado'; }
  else if(con2025 && btn.textContent !== 'Cargando…'){ btn.textContent = 'Ver sugerido'; }
  if(hint){
    if(!cli){
      hint.textContent = 'Si compraste en 2025 aquí tenemos tu Sugerido basado en tu compras';
    } else if(cli._comodin){
      hint.textContent = 'No disponible para cliente XXXXX · usa “Subir”';
    } else if(!listo){
      hint.textContent = 'Captura tu RFC para ver tu sugerido';
    } else if(!con2025){
      hint.textContent = 'Sin compra registrada en 2025 · usa “Subir” si tienes un archivo';
    } else if(yaAplicado){
      hint.textContent = `Sugerido ya agregado · ajústalo en el carrito`;
    } else {
      hint.textContent = `Listo para ${cli.n}`;
    }
  }
}

// Botón "un clic": usa el sugerido embebido para el cliente validado.
async function cargarSugeridoEmbebido(){
  if(!clienteListo()){ toast('Captura cliente y RFC antes de cargar el sugerido', 'error'); return; }
  const cli = state.cliente;
  if(!cli || cli._comodin){ toast('El sugerido aplica solo a clientes registrados (no comodín XXXXX)', 'error'); return; }
  // Candado anti-duplicado: si ya se aceptó el sugerido para este cliente, no reabrir para sumar otra vez.
  if(sugeridoAplicadoPara === String(cli.n).toUpperCase()){
    toast('Tu sugerido ya se agregó al pedido. Puedes ajustarlo en el carrito.', 'success', 3500);
    return;
  }
  const btn = document.getElementById('btn-sugerido');
  if(btn){ btn.disabled = true; btn.dataset._txt = btn.textContent; btn.textContent = 'Cargando…'; }
  try {
    const mapa = await cargarSugerido();
    const key = String(cli.n).toUpperCase();
    const sug = mapa[key];
    if(!sug || Object.keys(sug).length === 0){
      toast(`No hay pedido sugerido para el cliente ${cli.n}`, 'error', 3500);
      return;
    }
    const lineas = Object.entries(sug).map(([codigo, piezas]) => ({ codigo, piezas }));
    // NO se suma todavía: abre la previsualización editable. El alta al
    // carrito ocurre solo al pulsar "Aceptar y cargar en carrito".
    abrirSugeridoModal(lineas);
  } catch(err){
    console.error(err);
    toast('No se pudo leer el sugerido embebido en este navegador. Usa la opción de subir archivo.', 'error', 4500);
  } finally {
    // Restaura el texto transitorio "Cargando…" antes de recalcular el estado.
    if(btn && btn.textContent === 'Cargando…'){ btn.textContent = btn.dataset._txt || 'Ver sugerido'; }
    // Restaura el botón salvo que ya esté marcado como aplicado para este cliente.
    actualizarHeaderSugerido();
  }
}


// Uploader: lee un XLS/XLSX/CSV con columnas de código y piezas sugeridas.
// Acepta encabezados flexibles; busca una columna de código (UPC) y una de piezas.
function manejarArchivoSugerido(file){
  if(!clienteListo()){ toast('Captura cliente y RFC antes de subir un sugerido', 'error'); return; }
  if(!file) return;
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const wb = XLSX.read(new Uint8Array(e.target.result), { type: 'array' });
      const ws = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
      if(!rows.length){ toast('El archivo está vacío', 'error'); return; }
      // Detectar fila de encabezado y columnas de código / piezas
      const norm = s => String(s).toLowerCase().replace(/[\s._-]/g,'');
      let headRow = 0, colCod = -1, colPz = -1;
      for(let r = 0; r < Math.min(rows.length, 10); r++){
        const cells = rows[r].map(norm);
        const ci = cells.findIndex(c => c === 'codigo' || c === 'código' || c === 'upc' || c.includes('codigo'));
        const pi = cells.findIndex(c => (c.includes('sugerido') && c.includes('pieza')) || c === 'piezas' || c === 'cantidad' || c === 'sugeridoenpiezas2026');
        if(ci >= 0 && pi >= 0){ headRow = r; colCod = ci; colPz = pi; break; }
      }
      if(colCod < 0 || colPz < 0){
        toast('No se encontraron columnas de Código y de piezas sugeridas en el archivo', 'error', 4500);
        return;
      }
      const lineas = [];
      for(let r = headRow + 1; r < rows.length; r++){
        const cod = rows[r][colCod];
        const pz = rows[r][colPz];
        if(cod === '' || cod == null) continue;
        lineas.push({ codigo: cod, piezas: pz });
      }
      if(!lineas.length){ toast('No se encontraron líneas con código y piezas', 'error'); return; }
      // Mismo flujo que "Ver sugerido": abre la previsualización editable.
      // El alta al carrito ocurre solo al "Aceptar y cargar en carrito ahora".
      if(state.cliente && !state.cliente._comodin &&
         sugeridoAplicadoPara === String(state.cliente.n).toUpperCase()){
        toast('Tu sugerido ya se agregó al pedido. Puedes ajustarlo en el carrito.', 'success', 3500);
        return;
      }
      abrirSugeridoModal(lineas);
    } catch(err){
      console.error(err);
      toast('No se pudo leer el archivo. Verifica que sea XLSX/XLS/CSV válido.', 'error', 4500);
    }
  };
  reader.onerror = () => toast('Error al leer el archivo', 'error');
  reader.readAsArrayBuffer(file);
}

// ===== Promoción 3% + 3% (Muertos / Halloween) =====
// Descuento informativo por segmento sobre el SUBTOTAL SIN IVA:
//   - Si el subtotal sin IVA de productos MUERTOS supera el objetivo Muertos
//     del cliente (cli.objM, antes de IVA) -> 2% en ese segmento.
//   - Igual para HALLOWEEN con cli.objH.
// Ambos descuentos son independientes y acumulables.
// El descuento NO se aplica al total ni al XLS; sólo se muestra como motivación
// y se anota como mensaje en el XLS para aplicarlo en el sistema de facturación.
const PROMO_PCT = 0.03; // 3%

function getPromoData(){
  const cli = state.cliente;
  const items = Object.values(state.carrito);
  // Subtotales sin IVA por segmento
  let subM = 0, subH = 0;
  items.forEach(it => {
    if(!tienePrecio(it.p)) return;
    const sub = it.q * getPrecioPaquete(it.p); // sin IVA
    const g = (it.p.g || '').toUpperCase();
    if(g === 'MUERTOS') subM += sub;
    else if(g === 'HALLOWEEN') subH += sub;
  });
  // Objetivos: sólo aplican si el cliente es real (no comodín) y tiene objetivo > 0
  const real = cli && !cli._comodin;
  const objM = real ? (cli.objM || 0) : 0;
  const objH = real ? (cli.objH || 0) : 0;
  const hasM = objM > 0;
  const hasH = objH > 0;
  // Regla: ALCANZAR o superar la meta (>=) califica para el descuento.
  const okM = hasM && subM >= objM;
  const okH = hasH && subH >= objH;
  // Lógica escalonada:
  //  - Supera SOLO un segmento  -> 3% sobre ese segmento.
  //  - Supera AMBOS segmentos   -> 6% sobre cada segmento (bonus por acumular).
  // El bonus requiere dos objetivos reales (>0) ambos superados.
  const bonus = okM && okH;            // desbloquea el 6%
  const pct = bonus ? PROMO_PCT * 2 : PROMO_PCT;  // 0.06 ó 0.03
  return {
    real, subM, subH, objM, objH, hasM, hasH, okM, okH,
    bonus, pct,
    faltaM: hasM ? Math.max(0, objM - subM) : 0,
    faltaH: hasH ? Math.max(0, objH - subH) : 0,
    descM: okM ? subM * pct : 0,
    descH: okH ? subH * pct : 0,
    activo: hasM || hasH,
  };
}

// Pinta el panel de objetivos dentro del carrito (barras de avance por segmento)
function renderPromoPanel(){
  const wrap = $('promo-panel');
  if(!wrap) return;
  const d = getPromoData();
  if(!d.real || !d.activo){
    wrap.style.display = 'none';
    wrap.innerHTML = '';
    return;
  }
  wrap.style.display = 'block';
  const pctTxt = (d.pct * 100).toFixed(0);

  // Una fila por segmento con barra de avance.
  const segHTML = (label, emoji, sub, obj, has, ok, falta, desc) => {
    if(!has) return '';
    const prog = obj > 0 ? Math.min(100, (sub / obj) * 100) : 0;
    const estado = ok
      ? `<span class="promo-seg-win">✓ Meta alcanzada · −${pctTxt}% (${fmt(desc)})</span>`
      : `<span class="promo-seg-falta">Te faltan <strong>${fmt(falta)}</strong> para tu descuento</span>`;
    return `
      <div class="promo-seg ${ok?'is-win':''}">
        <div class="promo-seg-top">
          <span class="promo-seg-name">${emoji} ${label}</span>
          <span class="promo-seg-nums">${fmt(sub)} <span class="promo-seg-obj">/ meta ${fmt(obj)}</span></span>
        </div>
        <div class="promo-bar"><div class="promo-bar-fill ${ok?'win':''}" style="width:${prog}%"></div></div>
        <div class="promo-seg-state">${estado}</div>
      </div>`;
  };

  // Mensaje de incentivo según el estado:
  //  - bonus (ambos): celebra el 6%.
  //  - uno cumplido y el otro pendiente y existente: invita a desbloquear el 6%.
  //  - ninguno: explica la mecánica.
  let nudge = '';
  if(d.bonus){
    nudge = `<div class="promo-nudge bonus">🎉 ¡Bonus desbloqueado! Alcanzaste ambas metas: <strong>6% en todo tu pedido</strong> de temporada.</div>`;
  } else if(d.okM && d.hasH && !d.okH){
    nudge = `<div class="promo-nudge">Ya tienes <strong>3% en Muertos</strong>. Alcanza tu meta de Halloween (te faltan <strong>${fmt(d.faltaH)}</strong>) y tu descuento sube a <strong>6% en todo</strong>.</div>`;
  } else if(d.okH && d.hasM && !d.okM){
    nudge = `<div class="promo-nudge">Ya tienes <strong>3% en Halloween</strong>. Alcanza tu meta de Muertos (te faltan <strong>${fmt(d.faltaM)}</strong>) y tu descuento sube a <strong>6% en todo</strong>.</div>`;
  } else if(d.hasM && d.hasH){
    nudge = `<div class="promo-nudge soft">Alcanza una meta y obtén <strong>3%</strong> en ese segmento. Alcanza <strong>ambas</strong> y gana <strong>6% en todo tu pedido</strong>.</div>`;
  }

  const totalDesc = d.descM + d.descH;
  const headerExtra = totalDesc > 0
    ? `<span class="promo-head-save">Ahorro estimado: ${fmt(totalDesc)}</span>`
    : '';

  wrap.innerHTML = `
    <div class="promo-head">
      <span class="promo-badge ${d.bonus?'is-bonus':''}">Promoción 3% + 3%</span>
      ${headerExtra}
    </div>
    ${segHTML('Muertos', '💀', d.subM, d.objM, d.hasM, d.okM, d.faltaM, d.descM)}
    ${segHTML('Halloween', '🎃', d.subH, d.objH, d.hasH, d.okH, d.faltaH, d.descH)}
    ${nudge}
    <div class="promo-foot">El descuento se aplica al facturar. 3% al alcanzar una meta; 6% al alcanzar las dos (antes de IVA).</div>
  `;
}

// Banner fijo en el área del cliente: muestra la promo y los objetivos
// (Muertos / Halloween) del cliente desde que se valida, antes incluso de
// agregar productos, para que los tenga visibles.
function renderPromoClientBanner(){
  const el = $('promo-client-banner');
  if(!el) return;
  const cli = state.cliente;
  if(!cli || cli._comodin){ el.style.display = 'none'; el.innerHTML = ''; return; }
  const objM = cli.objM || 0;
  const objH = cli.objH || 0;
  if(objM <= 0 && objH <= 0){ el.style.display = 'none'; el.innerHTML = ''; return; }
  const cell = (emoji, label, obj) => obj > 0
    ? `<div class="pcb-cell"><span class="pcb-emoji">${emoji}</span>
         <span class="pcb-label">Meta ${label}</span>
         <span class="pcb-val">${fmt(obj)}</span></div>`
    : '';
  el.style.display = 'block';
  el.innerHTML = `
    <div class="pcb-title"><span class="pcb-badge">Promoción 3% + 3%</span>
      <span class="pcb-sub">Alcanza una meta y gana 3%; alcanza las dos y gana 6% en todo</span></div>
    <div class="pcb-grid">
      ${cell('💀','Muertos',objM)}
      ${cell('🎃','Halloween',objH)}
    </div>`;
}

function renderCarrito(){
  const items = Object.values(state.carrito);
  $('cart-count').textContent = items.length === 0 ? '0 productos' :
    `${items.length} ${items.length===1?'producto':'productos'}`;
  
  const list = $('cart-list');
  if(items.length === 0){
    list.innerHTML = '<div class="cart-empty">El carrito está vacío.<br>Agrega productos del catálogo →</div>';
  } else {
    list.innerHTML = items.map(it => {
      const p = it.p;
      const sin = !tienePrecio(p);
      const precioPq = getPrecioPaquete(p);
      const subtotal = sin ? 0 : (it.q * precioPq * 1.16);
      const subHTML = sin
        ? `<div class="cart-item-sub noprice">Producto sin precio</div>`
        : `<div class="cart-item-sub">${fmt(subtotal)}</div>`;
      return `<div class="cart-item">
        <div class="cart-item-info">
          <div class="cart-item-desc">${p.d}</div>
          <div class="cart-item-meta">${p.c} · paq c/${p.m} pz · ${p.g}</div>
          <div class="cart-item-qty">
            <div class="qty-input-wrap">
              <button class="qty-btn" onclick="window.__padcolor.cartQty('${p.c}', ${it.q-1})">−</button>
              <input class="qty-input" type="number" min="0" value="${it.q}" 
                     onchange="window.__padcolor.cartQty('${p.c}', this.value)">
              <button class="qty-btn" onclick="window.__padcolor.cartQty('${p.c}', ${it.q+1})">+</button>
            </div>
          </div>
        </div>
        <div class="cart-item-price">
          ${sin ? '<div class="cart-item-unit">—</div>' : 
            `<div class="cart-item-unit">${fmt(precioPq)}/paq</div>`}
          ${subHTML}
        </div>
        <button class="cart-item-remove" onclick="window.__padcolor.cartRemove('${p.c}')" title="Eliminar">×</button>
      </div>`;
    }).join('');
  }
  
  // Total
  const total = items.reduce((s, it) => {
    if(!tienePrecio(it.p)) return s;
    return s + it.q * getPrecioPaquete(it.p) * 1.16;
  }, 0);
  $('total-value').textContent = fmt(total);

  // Panel de objetivos / promoción 3%+3% (barras de avance por segmento)
  renderPromoPanel();

  // Total estimado con promoción aplicada (informativo; NO modifica el total
  // oficial ni el XLS). El descuento se calcula sobre subtotal sin IVA por
  // segmento y luego se le agrega IVA para mostrarlo como total estimado.
  const promo = getPromoData();
  const descTotalSinIva = promo.descM + promo.descH;
  const promoLine = $('total-promo-line');
  if(promoLine){
    if(descTotalSinIva > 0){
      const totalConPromo = total - (descTotalSinIva * 1.16);
      promoLine.style.display = 'block';
      promoLine.innerHTML =
        `<span class="promo-line-label">Con promoción 3%+3% (al facturar)</span>` +
        `<span class="promo-line-val">${fmt(totalConPromo)}</span>`;
    } else {
      promoLine.style.display = 'none';
      promoLine.innerHTML = '';
    }
  }
  
  // El aviso de pedido mínimo lo dispara actualizarFinalizar(), que
  // corre tras cada cambio de carrito y también al cambiar cliente/RFC.
  // (Antes había aquí un letrero permanente con la cifra; se removió
  // para no anclar al cliente a un monto bajo.)
  
  // Color del total + bloque "excede tu crédito" (cifras + CTA aumento)
  const box = $('total-box');
  box.classList.remove('green','yellow');
  const exceedBox = $('credit-exceed-box');
  const wasShown = exceedBox.style.display !== 'none' && exceedBox.style.display !== '';
  if(state.cliente && !state.cliente._comodin && items.length > 0){
    const lc = state.cliente.lc || 0;
    const sa = state.cliente.sa || 0;
    const disp = Math.max(0, lc - sa);
    // El bloque / botón de incremento de línea de crédito se dispara cuando
    // (pre-pedido con IVA + saldo actual) supera el límite de crédito × 1.30.
    if(!aplicaExcesoCredito(lc, sa, total)){
      box.classList.add('green');
      $('total-msg').textContent = '';
      exceedBox.style.display = 'none';
    } else {
      box.classList.add('yellow');
      $('total-msg').textContent = `Excede tu crédito disponible por ${fmt(Math.max(0, total - disp))}`;
      // Poblar cifras dentro del bloque amarillo y mostrarlo
      $('cli-lc').textContent = fmt(lc);
      $('cli-disp').textContent = fmt(disp);
      exceedBox.style.display = 'flex';
      // Si es la primera vez que aparece tras este render, hacer scroll al
      // fondo del carrito para que el cliente lo vea sin tener que buscar.
      if(!wasShown){
        const cartScroll = document.querySelector('.cart-scroll');
        if(cartScroll){
          setTimeout(() => { cartScroll.scrollTop = cartScroll.scrollHeight; }, 50);
        }
      }
    }
  } else {
    $('total-msg').textContent = '';
    exceedBox.style.display = 'none';
  }
}

// ===== Validación RFC =====
// Pedido mínimo: regla general $7,000; excepción $3,000 para clientes
// del listado curado (DATA.pm3000). Cliente comodín XXXXX usa la regla
// general. La definición exacta de los números de cliente con regla
// reducida vive en `data.json` (clave `pm3000`).
const PEDIDO_MIN_DEFAULT = 7000;
const PEDIDO_MIN_REDUCIDO = 3000;
const CLIENTS_PM3000_SET = new Set(
  (DATA.pm3000 || []).map(s => String(s).trim().toUpperCase())
);
function getPedidoMin(){
  const c = state.cliente;
  if(c && !c._comodin){
    const num = String(c.n || '').trim().toUpperCase();
    if(CLIENTS_PM3000_SET.has(num)) return PEDIDO_MIN_REDUCIDO;
  }
  return PEDIDO_MIN_DEFAULT;
}
// Aviso de pedido mínimo: ya NO se muestra la cifra de forma permanente
// (para no anclar al cliente a un monto bajo). En su lugar, cuando el
// carrito tiene productos pero aún no alcanza el mínimo aplicable, se
// dispara UNA alerta puntual indicando el monto que debe superar. La
// alerta se re-dispara solo al volver a entrar al estado "no alcanza"
// (no en cada tecla), y nunca con el carrito vacío.
let _minMetPrev = true; // arranca "true" para no alertar en carrito vacío inicial
function actualizarAvisoMin(total, itemCount){
  if(itemCount === 0){ _minMetPrev = true; return; }
  const pedidoMin = getPedidoMin();
  const cumple = total >= pedidoMin;
  if(!cumple && _minMetPrev){
    // Transición a "no alcanza": avisar una vez con el monto requerido.
    const minFmt = '$' + Number(pedidoMin).toLocaleString('es-MX');
    toast(`Tu pedido debe pasar ${minFmt} para finalizar`, 'error', 3500);
  }
  _minMetPrev = cumple;
}
function validarRfc(){
  const inp = $('cli-rfc');
  const v = (inp.value || '').toUpperCase().trim();
  if(v !== inp.value) inp.value = v;

  // Caso 1: cliente no validado todavía
  if(!state.cliente){
    inp.classList.remove('error','success');
    setMsg('rfc-msg', '', '');
    return false;
  }

  // Caso 2: RFC vacío
  if(!v){
    inp.classList.remove('error','success');
    setMsg('rfc-msg', state.cliente._comodin
      ? 'Captura el RFC del cliente.'
      : 'Captura el RFC del cliente para validar.', '');
    return false;
  }

  // Caso 3: formato inválido
  const formatoOk = /^[A-ZÑ&]{3,4}\d{6}[A-Z\d]{3}$/.test(v);
  if(!formatoOk){
    inp.classList.add('error');
    inp.classList.remove('success');
    setMsg('rfc-msg', 'Formato de RFC inválido.', 'error');
    return false;
  }

  // Caso 4: cliente comodín — solo se valida formato
  if(state.cliente._comodin){
    inp.classList.remove('error');
    inp.classList.add('success');
    setMsg('rfc-msg', 'RFC válido.', 'success');
    return true;
  }

  // Caso 5: cliente normal — debe coincidir con el RFC del catálogo
  const rfcCatalogo = (state.cliente.rfc || '').toUpperCase().trim();
  if(!rfcCatalogo){
    // Cliente no tiene RFC en catálogo: aceptar el capturado con formato válido
    inp.classList.remove('error');
    inp.classList.add('success');
    setMsg('rfc-msg', 'RFC válido (cliente sin RFC registrado).', 'success');
    return true;
  }
  if(v !== rfcCatalogo){
    inp.classList.add('error');
    inp.classList.remove('success');
    setMsg('rfc-msg', 'El RFC no coincide con el registrado para este cliente.', 'error');
    return false;
  }

  // Todo OK
  inp.classList.remove('error');
  inp.classList.add('success');
  setMsg('rfc-msg', 'RFC verificado ✓', 'success');
  return true;
}

// ===== Validar y habilitar finalizar =====
function actualizarFinalizar(){
  const items = Object.values(state.carrito);
  // Total con IVA
  const total = items.reduce((s, it) => {
    if(!tienePrecio(it.p)) return s;
    return s + it.q * getPrecioPaquete(it.p) * 1.16;
  }, 0);
  const minOk = total >= getPedidoMin();
  // Mantener sincronizado el aviso de pedido mínimo.
  actualizarAvisoMin(total, items.length);
  // "Revisar pedido" se habilita con cliente validado + carrito + mínimo.
  // El correo y el celular NO se exigen aquí: se validan dentro del modal
  // de revisión (en "Finalizar y descargar"), para que un cliente que cargó
  // un pedido sugerido pueda siempre abrir la revisión.
  const ok = clienteListo() && items.length > 0 && minOk;
  $('btn-finalize').disabled = !ok;
  actualizarHeaderSugerido();
}

// ===== Filtros UI =====
function buildFilterUI(){
  // Grupos como botones (estilo chip, toggle como "$E Precio Especial")
  const grpWrap = $('grupo-chips');
  if(grpWrap){
    grpWrap.innerHTML = GRUPOS.map(g => {
      const emoji = g.n.toUpperCase()==='MUERTOS' ? '💀'
                  : g.n.toUpperCase()==='HALLOWEEN' ? '🎃' : '🏷️';
      const label = g.n.charAt(0) + g.n.slice(1).toLowerCase();
      return `<button class="filter-chip grupo-chip" data-grupo="${g.n}">${emoji} ${label}<span class="qty">${g.q}</span></button>`;
    }).join('');
    grpWrap.querySelectorAll('.grupo-chip').forEach(btn => {
      btn.addEventListener('click', () => {
        const val = btn.dataset.grupo;
        // Toggle: si ya estaba activo, se desactiva (muestra todos)
        if(state.filterGrupo === val){
          state.filterGrupo = '';
          btn.classList.remove('active');
        } else {
          state.filterGrupo = val;
          grpWrap.querySelectorAll('.grupo-chip').forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
        }
        renderProductos();
      });
    });
  }

  // Página: input numérico (rango calculado desde páginas con productos)
  const paginas = new Set();
  PRODUCTS.forEach(p => p.p && paginas.add(p.p));
  const pagSorted = [...paginas].sort((a,b)=>a-b);
  const pagInput = $('filter-page');
  const pagClear = $('filter-page-clear');
  if(pagSorted.length){
    pagInput.min = pagSorted[0];
    pagInput.max = pagSorted[pagSorted.length-1];
    pagInput.placeholder = `${pagSorted[0]}-${pagSorted[pagSorted.length-1]}`;
  }
  function applyPagInput(){
    const v = pagInput.value.trim();
    const n = parseInt(v, 10);
    if(v === '' || isNaN(n)){
      state.filterPage = '';
      pagClear.style.display = 'none';
      pagInput.style.color = '';
    } else if(!paginas.has(n)){
      state.filterPage = String(n); // produce 0 resultados → empty state
      pagClear.style.display = 'inline';
      pagInput.style.color = 'var(--pad-red)';
    } else {
      state.filterPage = String(n);
      pagClear.style.display = 'inline';
      pagInput.style.color = '';
    }
    renderProductos();
  }
  pagInput.addEventListener('input', applyPagInput);
  pagInput.addEventListener('change', applyPagInput);
  pagClear.addEventListener('click', () => {
    pagInput.value = '';
    applyPagInput();
    pagInput.focus();
  });

  // Chips
  $('chip-especial').addEventListener('click', () => {
    state.filterEspecial = !state.filterEspecial;
    $('chip-especial').classList.toggle('active', state.filterEspecial);
    renderProductos();
  });
  $('chip-nuevos').addEventListener('click', () => {
    state.filterNuevos = !state.filterNuevos;
    $('chip-nuevos').classList.toggle('active', state.filterNuevos);
    renderProductos();
  });

  // Reset
  $('reset-filters').addEventListener('click', () => {
    state.filterEspecial = false;
    state.filterNuevos = false;
    state.filterGrupo = '';
    state.filterPage = '';
    state.search = '';
    $('search-input').value = '';
    $('search-clear').style.display = 'none';
    document.querySelectorAll('.filter-chip.active').forEach(c => c.classList.remove('active'));
    pagInput.value = '';
    $('filter-page-clear').style.display = 'none';
    renderProductos();
  });

  // Cargar más
  $('btn-load-more').addEventListener('click', () => {
    state.showLimit += 60;
    renderProductos();
  });

  // Conteos
  const espCount = PRODUCTS.filter(p => p.e).length;
  $('qty-especial').textContent = espCount;
  const nuevosCount = PRODUCTS.filter(p => p.n).length;
  $('qty-nuevos').textContent = nuevosCount;
}

// ===== Búsqueda =====
let searchTimer;
function setupSearch(){
  $('search-input').addEventListener('input', e => {
    const v = e.target.value;
    $('search-clear').style.display = v ? 'inline-flex' : 'none';
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => {
      state.search = v;
      state.showLimit = 60;
      renderProductos();
    }, 180);
  });
  $('search-clear').addEventListener('click', () => {
    $('search-input').value = '';
    $('search-clear').style.display = 'none';
    state.search = '';
    renderProductos();
  });
}

// ===== Cliente form =====
function setupClienteForm(){
  let cliTimer;
  $('cli-num').addEventListener('input', e => {
    clearTimeout(cliTimer);
    cliTimer = setTimeout(() => validarCliente(e.target.value), 350);
  });
  $('cli-num').addEventListener('blur', e => validarCliente(e.target.value));
  $('cli-email').addEventListener('input', actualizarFinalizar);
  $('cli-rfc').addEventListener('input', e => {
    // Forzar mayúsculas, quitar espacios
    let v = e.target.value.toUpperCase().replace(/\s/g,'');
    e.target.value = v;
    const eraValido = state._rfcValido === true;
    actualizarFinalizar();
    // Si el estado válido/inválido del RFC cambió, re-renderizar productos
    const esValido = clienteListo();
    if(eraValido !== esValido){
      state._rfcValido = esValido;
      renderProductos();
    }
  });
  $('cli-tel').addEventListener('input', e => {
    // Máscara (XX) XXXX-XXXX
    let d = e.target.value.replace(/\D/g,'').slice(0,10);
    let f = '';
    if(d.length > 0){ f = '('+d.slice(0,2); }
    if(d.length >= 2){ f += ') '; }
    if(d.length >= 2){ f += d.slice(2,6); }
    if(d.length >= 6){ f += '-'+d.slice(6,10); }
    e.target.value = f;
    actualizarFinalizar();
  });
  bloquearForm(true);
}

// ===== Finalizar pedido =====
function setupFinalizar(){
  $('btn-finalize').addEventListener('click', abrirRevisionPedido);
  $('btn-credit').addEventListener('click', abrirSolicitudCredito);
  const btnNuevo = $('btn-new-order');
  if(btnNuevo) btnNuevo.addEventListener('click', nuevoPedido);

  const btnSug = $('btn-sugerido');
  if(btnSug) btnSug.addEventListener('click', cargarSugeridoEmbebido);
  const fileSug = $('file-sugerido');
  if(fileSug) fileSug.addEventListener('change', (e) => {
    manejarArchivoSugerido(e.target.files[0]);
    e.target.value = ''; // permite recargar el mismo archivo
  });
}
// ===== Previsualización del Pedido Sugerido (modal editable) =====
// "Ver sugerido" abre este modal con las líneas sugeridas (recortadas a
// existencia). El cliente puede editar/eliminar antes de aceptar. El alta
// al carrito ocurre SOLO al pulsar "Aceptar y cargar en carrito", momento
// en que se activa el candado anti-duplicado.
let sugDraft = null;        // { codigo: { p, q } }  borrador editable del sugerido
let sugWired = false;

function abrirSugeridoModal(lineas){
  const cli = state.cliente;
  if(!cli || cli._comodin) return;
  // Construir borrador desde las líneas sugeridas, recortando a existencia
  // y omitiendo agotados / códigos inexistentes.
  sugDraft = {};
  let recortados = 0, agotados = 0, sinProducto = 0;
  lineas.forEach(({codigo, piezas}) => {
    // Normaliza el código: si viene como número (Excel), evita decimales/
    // notación científica convirtiéndolo a entero cuando aplique.
    let cod = (typeof codigo === 'number' && isFinite(codigo))
      ? String(Math.round(codigo))
      : String(codigo).trim();
    let pz = parseInt(piezas, 10) || 0;
    if(pz <= 0) return;
    const p = PRODUCTS.find(x => String(x.c) === cod);
    if(!p){ sinProducto++; return; }
    const max = getStock(p);
    if(max <= 0){ agotados++; return; }
    if(pz > max){ pz = max; recortados++; }
    sugDraft[cod] = { p, q: pz };
  });
  if(Object.keys(sugDraft).length === 0){
    toast('Tu sugerido no tiene productos disponibles en existencia ahora mismo.', 'error', 4000);
    sugDraft = null;
    return;
  }
  renderSugeridoModal();
}

function renderSugeridoModal(){
  const cli = state.cliente;
  if(!cli || !sugDraft) return;
  const items = Object.values(sugDraft).filter(it => it.q > 0);

  const ordenGrupo = g => g === 'MUERTOS' ? 0 : g === 'HALLOWEEN' ? 1 : 2;
  const emoji = g => g === 'MUERTOS' ? '💀' : g === 'HALLOWEEN' ? '🎃' : '📦';
  const porGrupo = {};
  items.forEach(it => {
    const g = (it.p.g || 'OTROS').toUpperCase();
    (porGrupo[g] = porGrupo[g] || []).push(it);
  });
  const grupos = Object.keys(porGrupo).sort((a,b)=>ordenGrupo(a)-ordenGrupo(b));

  let totalPiezas = 0;
  let cuerpo = '';
  grupos.forEach(g => {
    const lista = porGrupo[g];
    let subGrupo = 0;
    const filas = lista.map(it => {
      const sin = !tienePrecio(it.p);
      const pq = sin ? 0 : getPrecioPaquete(it.p);
      const sub = it.q * pq * 1.16;
      subGrupo += sub;
      totalPiezas += it.q * (it.p.m || 1);
      const max = getStock(it.p);
      const u2025 = pz2025De(it.p.c);
      return `<tr>
        <td class="rev-cod">${it.p.c}</td>
        <td class="rev-desc">${it.p.d}</td>
        <td class="rev-2025">${u2025 ? fmtInt(u2025) : '—'}</td>
        <td class="rev-edit">
          <div class="rev-stepper">
            <button class="rev-step" data-sact="dec" data-cod="${it.p.c}" aria-label="Restar">−</button>
            <input class="rev-qty sug-qty" type="text" inputmode="numeric" value="${it.q}" data-cod="${it.p.c}" data-max="${max}">
            <button class="rev-step" data-sact="inc" data-cod="${it.p.c}" aria-label="Sumar">+</button>
          </div>
        </td>
        <td class="rev-num" id="sug-imp-${it.p.c}">${sin ? '<span class="rev-sinprecio">sin precio</span>' : fmt(sub)}</td>
        <td class="rev-del"><button class="rev-x" data-sact="del" data-cod="${it.p.c}" aria-label="Eliminar">✕</button></td>
      </tr>`;
    }).join('');
    cuerpo += `<div class="rev-grupo">
      <div class="rev-grupo-head"><span>${emoji(g)} ${g}</span><span id="sug-subg-${g}">${fmt(subGrupo)}</span></div>
      <table class="rev-table">
        <thead><tr><th>Código</th><th>Descripción</th><th class="rev-2025-h">Pz 2025</th><th class="rev-edit-h">Cantidad (paq)</th><th>Importe</th><th></th></tr></thead>
        <tbody>${filas}</tbody>
      </table>
    </div>`;
  });

  const subtotalSinIVA = items.reduce((s, it) => tienePrecio(it.p) ? s + it.q * getPrecioPaquete(it.p) : s, 0);
  const iva = subtotalSinIVA * 0.16;
  const totalConIVA = subtotalSinIVA + iva;

  const vacio = items.length === 0;
  const numCli = cli.n;
  const razon = cli.rs || cli.nc || '';

  const body = `
    <div class="rev-meta">
      <div><span class="rev-meta-l">Cliente</span><span class="rev-meta-v">${numCli}${razon ? ' · ' + razon : ''}</span></div>
      <div><span class="rev-meta-l">Renglones sugeridos</span><span class="rev-meta-v">${items.length} · ${fmtInt(totalPiezas)} pz</span></div>
    </div>
    <div class="rev-sug-nota">✨ Este es tu pedido sugerido con base en tu compra 2025. Ajústalo a tu gusto y pulsa <strong>Aceptar y cargar en carrito</strong>: se suma una sola vez. O usa el botón verde para <strong>descargarlo</strong>, trabajarlo por fuera y subirlo después.</div>
    ${vacio ? '<div class="rev-vacio">Quitaste todos los renglones del sugerido. Cierra para volver al catálogo.</div>' : cuerpo}
    <div class="rev-tot">
      <div class="rev-tot-row"><span>Subtotal</span><span id="sug-tot-sub">${fmt(subtotalSinIVA)}</span></div>
      <div class="rev-tot-row"><span>IVA (16%)</span><span id="sug-tot-iva">${fmt(iva)}</span></div>
      <div class="rev-tot-row rev-tot-grand"><span>Total</span><span id="sug-tot-grand">${fmt(totalConIVA)}</span></div>
    </div>
  `;

  const footer = `
    <div class="rev-footer">
      <button class="filter-toggle" data-close>← Seguir comprando</button>
      <div class="rev-footer-right">
        <button class="sug-descargar" id="sug-descargar-btn" ${vacio ? 'disabled' : ''}>Descargarlo para trabajarlo y cargarlo después</button>
        <button class="btn-primary rev-finalize" id="sug-aceptar-btn" ${vacio ? 'disabled' : ''}>Aceptar y cargar en carrito ahora</button>
      </div>
    </div>
  `;

  showModal('Tu pedido sugerido', body, footer, { wide: true });
  cablearSugerido();
}

function cablearSugerido(){
  const body = $('modal-body');
  if(body && !sugWired){
    body.addEventListener('click', sugOnClick);
    body.addEventListener('input', sugOnInput);
    body.addEventListener('change', sugOnInput);
    sugWired = true;
  }
  const a = $('sug-aceptar-btn');
  if(a && !a.disabled) a.addEventListener('click', sugAceptar);
  const d = $('sug-descargar-btn');
  if(d && !d.disabled) d.addEventListener('click', sugDescargar);
}

function sugOnClick(e){
  const btn = e.target.closest('[data-sact]');
  if(!btn || !sugDraft) return;
  const cod = btn.dataset.cod;
  const act = btn.dataset.sact;
  const it = sugDraft[cod];
  if(!it) return;
  if(act === 'del'){ delete sugDraft[cod]; renderSugeridoModal(); return; }
  const max = getStock(it.p);
  if(act === 'inc'){ it.q = Math.min(max, it.q + 1); renderSugeridoModal(); }
  else if(act === 'dec'){
    it.q = it.q - 1;
    if(it.q <= 0) delete sugDraft[cod];
    renderSugeridoModal();
  }
}

function sugOnInput(e){
  const inp = e.target.closest('.sug-qty');
  if(!inp || !sugDraft) return;
  const cod = inp.dataset.cod;
  const it = sugDraft[cod];
  if(!it) return;
  const max = parseInt(inp.dataset.max, 10) || 0;

  // Mientras se TECLEA (input): no reconstruir el modal (eso perdía el foco y
  // saltaba el scroll). Sólo actualizar el borrador y refrescar importes/totales
  // en su lugar. Se permite el campo vacío de forma temporal sin tocar nada.
  if(e.type === 'input'){
    const raw = String(inp.value).replace(/\D/g,'');
    if(raw === ''){ return; }            // borrado temporal: esperar a que teclee
    let v = parseInt(raw, 10);
    if(isNaN(v) || v <= 0) return;       // 0 / inválido: no aplicar aún (se maneja en blur)
    if(v > max){ v = max; inp.value = String(v); } // tope por existencia
    it.q = v;
    actualizarTotalesSugeridoLigero();
    return;
  }

  // Al SALIR del campo (change): consolidar. Aquí sí re-render sólo si hace
  // falta cambiar la estructura (cantidad 0 -> eliminar renglón).
  let v = parseInt(String(inp.value).replace(/\D/g,''), 10);
  if(isNaN(v) || v <= 0){ delete sugDraft[cod]; renderSugeridoModal(); return; }
  if(v > max) v = max;
  it.q = v;
  inp.value = String(v);                 // normaliza lo mostrado
  actualizarTotalesSugeridoLigero();     // sin reconstruir: conserva foco y scroll
}

// Actualiza importes por renglón, subtotales por grupo y totales del modal
// sugerido sin reconstruir la tabla (para no perder el foco ni saltar el scroll).
function actualizarTotalesSugeridoLigero(){
  if(!sugDraft) return;
  const items = Object.values(sugDraft).filter(it => it.q > 0);
  // Importe por renglón
  items.forEach(it => {
    const cell = $('sug-imp-' + it.p.c);
    if(cell && tienePrecio(it.p)){
      cell.textContent = fmt(it.q * getPrecioPaquete(it.p) * 1.16);
    }
  });
  // Subtotales por grupo
  const subPorGrupo = {};
  items.forEach(it => {
    if(!tienePrecio(it.p)) return;
    const g = (it.p.g || 'OTROS').toUpperCase();
    subPorGrupo[g] = (subPorGrupo[g] || 0) + it.q * getPrecioPaquete(it.p) * 1.16;
  });
  Object.keys(subPorGrupo).forEach(g => {
    const el = $('sug-subg-' + g);
    if(el) el.textContent = fmt(subPorGrupo[g]);
  });
  // Totales generales
  const subtotalSinIVA = items.reduce((s, it) => tienePrecio(it.p) ? s + it.q * getPrecioPaquete(it.p) : s, 0);
  const iva = subtotalSinIVA * 0.16;
  const elSub = $('sug-tot-sub'), elIva = $('sug-tot-iva'), elGrand = $('sug-tot-grand');
  if(elSub) elSub.textContent = fmt(subtotalSinIVA);
  if(elIva) elIva.textContent = fmt(iva);
  if(elGrand) elGrand.textContent = fmt(subtotalSinIVA + iva);
}

// "Descargarlo para trabajarlo y cargarlo después": genera un XLS con el
// layout estándar del sugerido (Código + Sugerido en piezas 2026), que el
// botón "Subir" puede volver a leer. NO carga al carrito ni toca el candado.
function sugDescargar(){
  const cli = state.cliente;
  if(!cli || cli._comodin || !sugDraft){ toast('No hay sugerido para descargar', 'error'); return; }
  const items = Object.values(sugDraft).filter(it => it.q > 0);
  if(items.length === 0){ toast('No hay renglones que descargar', 'error'); return; }

  // Ordenar por grupo (Muertos, Halloween, Otros) y luego por código.
  const ordenGrupo = g => g === 'MUERTOS' ? 0 : g === 'HALLOWEEN' ? 1 : 2;
  items.sort((x, y) => {
    const gx = (x.p.g || 'OTROS').toUpperCase(), gy = (y.p.g || 'OTROS').toUpperCase();
    const og = ordenGrupo(gx) - ordenGrupo(gy);
    return og !== 0 ? og : String(x.p.c).localeCompare(String(y.p.c));
  });

  // Encabezados: la columna "Código" y "Sugerido en piezas 2026" son las que
  // lee el uploader (manejarArchivoSugerido). Las demás son de apoyo para
  // trabajar el archivo (no estorban a la lectura).
  const rows = [['Código', 'Descripción', 'Grupo', 'Pz 2025', 'Sugerido en piezas 2026', 'Precio paquete', 'Importe (sin IVA)']];
  items.forEach(it => {
    const sin = !tienePrecio(it.p);
    const pq = sin ? 0 : getPrecioPaquete(it.p);
    const u2025 = pz2025De(it.p.c);
    rows.push([
      String(it.p.c),
      it.p.d,
      (it.p.g || 'OTROS').toUpperCase(),
      u2025 || 0,
      it.q,
      pq,
      it.q * pq
    ]);
  });

  const ws = XLSX.utils.aoa_to_sheet(rows);
  const headerStyle = {
    font:{name:'Calibri', sz:10, bold:true, color:{rgb:'FFFFFF'}},
    fill:{patternType:'solid', fgColor:{rgb:'0A3D8F'}},
    alignment:{horizontal:'center', vertical:'center'},
    border:{
      top:{style:'thin',color:{rgb:'D8DDE6'}},
      bottom:{style:'thin',color:{rgb:'D8DDE6'}},
      left:{style:'thin',color:{rgb:'D8DDE6'}},
      right:{style:'thin',color:{rgb:'D8DDE6'}},
    },
  };
  const moneyFmt = '"$"#,##0.00;[Red]-"$"#,##0.00';
  ['A1','B1','C1','D1','E1','F1','G1'].forEach(addr => { if(ws[addr]) ws[addr].s = headerStyle; });
  const totalRows = rows.length;
  for(let r = 2; r <= totalRows; r++){
    ['F','G'].forEach(col => {
      const a = col + r;
      if(ws[a]){ ws[a].t = 'n'; ws[a].z = moneyFmt; ws[a].s = {numFmt: moneyFmt, alignment:{horizontal:'right'}}; }
    });
    ['D','E'].forEach(col => {
      const a = col + r;
      if(ws[a]){ ws[a].t = 'n'; ws[a].s = {alignment:{horizontal:'center'}}; }
    });
  }
  ws['!cols'] = [{wch:14},{wch:50},{wch:12},{wch:10},{wch:22},{wch:15},{wch:18}];
  ws['!rows'] = [{hpt:22}];
  // Forzar la columna Código (A) como TEXTO para que Excel no convierta los
  // UPC largos a notación científica ni pierda ceros a la izquierda.
  for(let r = 2; r <= totalRows; r++){
    const a = 'A' + r;
    if(ws[a]){ ws[a].t = 's'; ws[a].z = '@'; ws[a].s = Object.assign({}, ws[a].s, {numFmt:'@'}); }
  }

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Sugerido');

  // Nombre: Sugerido_<numCliente>_<ddmmyy>.xlsx
  const today = new Date();
  const ddmmyy = String(today.getDate()).padStart(2,'0') +
                 String(today.getMonth()+1).padStart(2,'0') +
                 String(today.getFullYear()).slice(-2);
  const numCli = String(cli.n).replace(/[\[\]\*\?\/\\:]/g,'_');
  const filename = `Sugerido_${numCli}_${ddmmyy}.xlsx`;

  XLSX.writeFile(wb, filename);
  toast(`Descargado como ${filename}. Trabájalo y vuelve a subirlo con “Subir”.`, 'success', 5000);
}

// "Aceptar y cargar en carrito ahora": suma el borrador al carrito UNA sola
// vez, activa el candado anti-duplicado y cierra el modal.
function sugAceptar(){
  const cli = state.cliente;
  if(!cli || cli._comodin || !sugDraft) return;
  const key = String(cli.n).toUpperCase();
  // Doble protección contra doble clic.
  if(sugeridoAplicadoPara === key){
    toast('Tu sugerido ya se agregó al pedido. Puedes ajustarlo en el carrito.', 'success', 3500);
    closeModal();
    return;
  }
  const lineas = Object.values(sugDraft)
    .filter(it => it.q > 0)
    .map(it => ({ codigo: it.p.c, piezas: it.q }));
  if(lineas.length === 0){
    toast('No hay renglones que cargar.', 'error');
    return;
  }
  // Marca el candado ANTES de aplicar para que actualizarHeaderSugerido lo respete.
  sugeridoAplicadoPara = key;
  aplicarSugeridoLineas(lineas);
  sugDraft = null;
  actualizarHeaderSugerido();
  closeModal();
}

// ===== Revisión del pedido (modal editable, modelo borrador) =====
// El modal abre con una COPIA editable del carrito (revDraft). El cliente
// puede sumar/restar/escribir cantidades o eliminar renglones; los totales
// del modal se recalculan en vivo, pero el carrito real NO cambia hasta
// "Guardar cambios". Mientras existan cambios sin guardar, "Finalizar y
// descargar" queda bloqueado (hay que guardar primero). Muestra además la
// columna "Pz 2025" como referencia de la compra del año anterior.
let revDraft = null;     // { codigo: { p, q } }  copia editable
let revOriginal = null;  // { codigo: q }          snapshot para detectar cambios

function abrirRevisionPedido(){
  const items = Object.values(state.carrito);
  if(!state.cliente || items.length === 0) return;
  // Construir borrador y snapshot a partir del carrito actual.
  revDraft = {};
  revOriginal = {};
  items.forEach(it => {
    revDraft[it.p.c] = { p: it.p, q: it.q };
    revOriginal[it.p.c] = it.q;
  });
  renderRevision();
}

// ¿El borrador difiere del carrito guardado?
function revHayCambios(){
  if(!revDraft || !revOriginal) return false;
  const codigos = new Set([...Object.keys(revDraft), ...Object.keys(revOriginal)]);
  for(const c of codigos){
    const q = revDraft[c] ? revDraft[c].q : 0;
    const o = revOriginal[c] || 0;
    if(q !== o) return true;
  }
  return false;
}

function renderRevision(){
  const cli = state.cliente;
  if(!cli || !revDraft) return;
  const items = Object.values(revDraft).filter(it => it.q > 0);

  // Agrupar por segmento (MUERTOS / HALLOWEEN / OTROS).
  const ordenGrupo = g => g === 'MUERTOS' ? 0 : g === 'HALLOWEEN' ? 1 : 2;
  const emoji = g => g === 'MUERTOS' ? '💀' : g === 'HALLOWEEN' ? '🎃' : '📦';
  const porGrupo = {};
  items.forEach(it => {
    const g = (it.p.g || 'OTROS').toUpperCase();
    (porGrupo[g] = porGrupo[g] || []).push(it);
  });
  const grupos = Object.keys(porGrupo).sort((a,b)=>ordenGrupo(a)-ordenGrupo(b));

  let totalPiezas = 0;
  let cuerpo = '';
  grupos.forEach(g => {
    const lista = porGrupo[g];
    let subGrupo = 0;
    const filas = lista.map(it => {
      const sin = !tienePrecio(it.p);
      const pq = sin ? 0 : getPrecioPaquete(it.p);
      const sub = it.q * pq * 1.16;
      subGrupo += sub;
      totalPiezas += it.q * (it.p.m || 1);
      const max = getStock(it.p);
      const u2025 = pz2025De(it.p.c);
      return `<tr>
        <td class="rev-cod">${it.p.c}</td>
        <td class="rev-desc">${it.p.d}</td>
        <td class="rev-2025">${u2025 ? fmtInt(u2025) : '—'}</td>
        <td class="rev-edit">
          <div class="rev-stepper">
            <button class="rev-step" data-act="dec" data-cod="${it.p.c}" aria-label="Restar">−</button>
            <input class="rev-qty" type="text" inputmode="numeric" value="${it.q}" data-cod="${it.p.c}" data-max="${max}">
            <button class="rev-step" data-act="inc" data-cod="${it.p.c}" aria-label="Sumar">+</button>
          </div>
        </td>
        <td class="rev-num">${sin ? '<span class="rev-sinprecio">sin precio</span>' : fmt(sub)}</td>
        <td class="rev-del"><button class="rev-x" data-act="del" data-cod="${it.p.c}" aria-label="Eliminar">✕</button></td>
      </tr>`;
    }).join('');
    cuerpo += `<div class="rev-grupo">
      <div class="rev-grupo-head"><span>${emoji(g)} ${g}</span><span>${fmt(subGrupo)}</span></div>
      <table class="rev-table">
        <thead><tr><th>Código</th><th>Descripción</th><th class="rev-2025-h">Pz 2025</th><th class="rev-edit-h">Cantidad (paq)</th><th>Importe</th><th></th></tr></thead>
        <tbody>${filas}</tbody>
      </table>
    </div>`;
  });

  const subtotalSinIVA = items.reduce((s, it) => tienePrecio(it.p) ? s + it.q * getPrecioPaquete(it.p) : s, 0);
  const iva = subtotalSinIVA * 0.16;
  const totalConIVA = subtotalSinIVA + iva;

  // Promoción 3%+3% calculada sobre el BORRADOR (no sobre el carrito guardado).
  const d = getPromoDataDe(items);
  let promoHTML = '';
  if(d.real && d.activo){
    const pctTxt = (d.pct * 100).toFixed(0);
    const descTotal = (d.descM + d.descH) * 1.16;
    if(d.okM || d.okH){
      // Desglose por segmento alcanzado, con el descuento (con IVA) de cada uno.
      // Es clave aclarar que el descuento aplica SOLO a la mercancía de cada
      // segmento alcanzado, no a todo el pedido.
      const lineas = [];
      if(d.okM) lineas.push(`<li><span class="rev-promo-seg">💀 Muertos</span> · <strong>${pctTxt}%</strong> sobre la mercancía de Muertos · ${fmt(d.descM * 1.16)}</li>`);
      if(d.okH) lineas.push(`<li><span class="rev-promo-seg">🎃 Halloween</span> · <strong>${pctTxt}%</strong> sobre la mercancía de Halloween · ${fmt(d.descH * 1.16)}</li>`);

      const titulo = d.bonus
        ? `🎁 ¡Ganaste la promoción en ambos segmentos! ${pctTxt}% en Muertos y Halloween`
        : (d.okM
            ? `🎁 ¡Ganaste la promoción! ${pctTxt}% en Muertos`
            : `🎁 ¡Ganaste la promoción! ${pctTxt}% en Halloween`);

      // Aclaración de alcance según uno o ambos segmentos.
      const alcance = d.bonus
        ? `El descuento se aplica a la mercancía solicitada de <strong>Muertos</strong> y de <strong>Halloween</strong> (cada segmento por separado), no al resto del pedido.`
        : (d.okM
            ? `El descuento se aplica únicamente a la mercancía solicitada de <strong>Muertos</strong>, no a todo el pedido.`
            : `El descuento se aplica únicamente a la mercancía solicitada de <strong>Halloween</strong>, no a todo el pedido.`);

      promoHTML = `<div class="rev-promo rev-promo-ok">
        <div class="rev-promo-t">${titulo}</div>
        <ul class="rev-promo-list">${lineas.join('')}</ul>
        <div class="rev-promo-d">${alcance} Al facturar se aplicará un descuento total aproximado de <strong>${fmt(descTotal)}</strong>.</div>
      </div>`;
    } else {
      const falta = [];
      if(d.hasM && !d.okM) falta.push(`Muertos: faltan ${fmt(d.faltaM * 1.16)}`);
      if(d.hasH && !d.okH) falta.push(`Halloween: faltan ${fmt(d.faltaH * 1.16)}`);
      promoHTML = `<div class="rev-promo rev-promo-pend">
        <div class="rev-promo-t">🎯 Promoción 3%+3% disponible</div>
        <div class="rev-promo-d">${falta.join(' · ')} para alcanzar tu meta y ganar el descuento.</div>
      </div>`;
    }
  }

  const pedidoMin = getPedidoMin();
  const minOk = totalConIVA >= pedidoMin;
  const minHTML = minOk
    ? `<div class="rev-min rev-min-ok">✓ Pedido mínimo cumplido</div>`
    : `<div class="rev-min rev-min-no">Tu pedido debe pasar $${Number(pedidoMin).toLocaleString('es-MX')} para finalizar · faltan ${fmt(pedidoMin - totalConIVA)}</div>`;

  // Contacto (correo + celular) requerido para finalizar.
  const email = $('cli-email').value.trim();
  const tel = $('cli-tel').value.replace(/\D/g,'');
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const telOk = tel.length === 10;
  const contactoOk = emailOk && telOk;
  let contactoHTML = '';
  if(!contactoOk){
    const faltan = [];
    if(!emailOk) faltan.push('Correo');
    if(!telOk) faltan.push('Celular (10 dígitos)');
    contactoHTML = `<div class="rev-contacto">⚠ Captura <strong>${faltan.join(' y ')}</strong> en el carrito para poder finalizar.</div>`;
  }

  const cambios = revHayCambios();
  const vacio = items.length === 0;
  let cambiosHTML = '';
  if(cambios){
    cambiosHTML = `<div class="rev-cambios">✎ Tienes cambios sin guardar. Guarda para poder finalizar.</div>`;
  }

  const puedeFinalizar = minOk && contactoOk && !cambios && !vacio;

  const numCli = cli._comodin ? 'XXXXX' : cli.n;
  const razon = cli._comodin ? 'Cliente comodín' : (cli.rs || cli.nc || '');

  const body = `
    <div class="rev-meta">
      <div><span class="rev-meta-l">Cliente</span><span class="rev-meta-v">${numCli}${razon ? ' · ' + razon : ''}</span></div>
      <div><span class="rev-meta-l">Renglones</span><span class="rev-meta-v">${items.length} · ${fmtInt(totalPiezas)} pz</span></div>
    </div>
    ${vacio ? '<div class="rev-vacio">El pedido quedó vacío. Agrega productos o cierra para volver al catálogo.</div>' : cuerpo}
    <div class="rev-tot">
      <div class="rev-tot-row"><span>Subtotal</span><span>${fmt(subtotalSinIVA)}</span></div>
      <div class="rev-tot-row"><span>IVA (16%)</span><span>${fmt(iva)}</span></div>
      <div class="rev-tot-row rev-tot-grand"><span>Total</span><span>${fmt(totalConIVA)}</span></div>
    </div>
    ${promoHTML}
    ${minHTML}
    ${contactoHTML}
    ${cambiosHTML}
  `;

  const footer = `
    <div class="rev-footer">
      <button class="filter-toggle" data-close>← Seguir comprando</button>
      <div class="rev-footer-right">
        <button class="rev-guardar ${cambios ? 'rev-guardar-activo' : ''}" id="rev-guardar-btn" ${cambios ? '' : 'disabled'}>Guardar cambios</button>
        <button class="btn-primary rev-finalize" id="rev-finalize-btn" ${puedeFinalizar ? '' : 'disabled'}>Finalizar y descargar</button>
      </div>
    </div>
  `;

  showModal('Revisa tu pre-pedido', body, footer, { wide: true });
  cablearRevision();
}

// Conecta los controles de edición del modal. Los listeners de delegación
// sobre #modal-body se instalan UNA sola vez (revWired) porque showModal
// reemplaza el innerHTML pero conserva el elemento; así no se acumulan.
let revWired = false;
function cablearRevision(){
  const body = $('modal-body');
  if(body && !revWired){
    body.addEventListener('click', revOnClick);
    body.addEventListener('input', revOnInput);
    body.addEventListener('change', revOnInput);
    revWired = true;
  }
  // El footer SÍ se reconstruye en cada render; sus botones son nuevos cada vez.
  const g = $('rev-guardar-btn');
  if(g && revHayCambios()) g.addEventListener('click', revGuardar);
  const f = $('rev-finalize-btn');
  if(f && !f.disabled) f.addEventListener('click', () => { closeModal(); generarPedido(); });
}

function revOnClick(e){
  const btn = e.target.closest('[data-act]');
  if(!btn) return;
  const cod = btn.dataset.cod;
  const act = btn.dataset.act;
  const it = revDraft[cod];
  if(!it) return;
  if(act === 'del'){
    delete revDraft[cod];
    renderRevision();
    return;
  }
  const max = getStock(it.p);
  if(act === 'inc'){ it.q = Math.min(max, it.q + 1); renderRevision(); }
  else if(act === 'dec'){
    it.q = it.q - 1;
    if(it.q <= 0) delete revDraft[cod];
    renderRevision();
  }
}

function revOnInput(e){
  if(e.target.closest('.sug-qty')) return; // input del modal sugerido, lo maneja sugOnInput
  const inp = e.target.closest('.rev-qty');
  if(!inp || !revDraft) return;
  const cod = inp.dataset.cod;
  const it = revDraft[cod];
  if(!it) return;
  const max = parseInt(inp.dataset.max, 10) || 0;
  let v = parseInt(String(inp.value).replace(/\D/g,''), 10);
  if(isNaN(v)) return; // permitir borrado temporal sin re-render
  if(v > max) v = max;
  if(v <= 0){ delete revDraft[cod]; renderRevision(); return; }
  it.q = v;
  // Re-render en 'change' (al salir del campo) para no perder el foco al teclear.
  if(e.type === 'change') renderRevision();
  else actualizarTotalesRevisionLigero();
}

// Actualiza solo los totales/avisos mientras el usuario teclea, sin
// re-renderizar toda la tabla (para no perder el foco del input).
function actualizarTotalesRevisionLigero(){
  // Recalcular y reflejar el botón guardar como activo (hay cambios).
  const g = $('rev-guardar-btn');
  if(g){
    const cambios = revHayCambios();
    g.disabled = !cambios;
    g.classList.toggle('rev-guardar-activo', cambios);
  }
  // Bloquear finalizar si hay cambios sin guardar.
  const f = $('rev-finalize-btn');
  if(f && revHayCambios()) f.disabled = true;
}

function revGuardar(){
  // Aplica el borrador al carrito real.
  Object.keys(state.carrito).forEach(c => { if(!revDraft[c]) delete state.carrito[c]; });
  Object.values(revDraft).forEach(it => {
    if(it.q > 0) state.carrito[it.p.c] = { p: it.p, q: it.q };
  });
  // Re-sincronizar snapshot (ya no hay cambios pendientes).
  revOriginal = {};
  Object.values(revDraft).forEach(it => { if(it.q > 0) revOriginal[it.p.c] = it.q; });
  // Refrescar vista principal.
  renderCarrito();
  actualizarFinalizar();
  renderProductos();
  toast('✓ Cambios guardados en el pedido', 'success');
  renderRevision();
}

// Variante de getPromoData que opera sobre una lista de items dada
// (para calcular la promoción del borrador en el modal).
function getPromoDataDe(items){
  const cli = state.cliente;
  let subM = 0, subH = 0;
  items.forEach(it => {
    if(!tienePrecio(it.p)) return;
    const sub = it.q * getPrecioPaquete(it.p);
    const g = (it.p.g || '').toUpperCase();
    if(g === 'MUERTOS') subM += sub;
    else if(g === 'HALLOWEEN') subH += sub;
  });
  const real = cli && !cli._comodin;
  const objM = real ? (cli.objM || 0) : 0;
  const objH = real ? (cli.objH || 0) : 0;
  const hasM = objM > 0, hasH = objH > 0;
  const okM = hasM && subM >= objM;
  const okH = hasH && subH >= objH;
  const bonus = okM && okH;
  const pct = bonus ? PROMO_PCT * 2 : PROMO_PCT;
  return { real, subM, subH, objM, objH, hasM, hasH, okM, okH, bonus, pct,
    faltaM: hasM ? Math.max(0, objM - subM) : 0,
    faltaH: hasH ? Math.max(0, objH - subH) : 0,
    descM: okM ? subM * pct : 0,
    descH: okH ? subH * pct : 0,
    activo: hasM || hasH };
}


function generarPedido(){
  const items = Object.values(state.carrito);
  if(!state.cliente || items.length === 0) return;

  const cli = state.cliente;
  const numCli = cli._comodin ? 'XXXXX' : cli.n;
  const today = new Date();
  const ddmmyy = String(today.getDate()).padStart(2,'0') +
                 String(today.getMonth()+1).padStart(2,'0') +
                 String(today.getFullYear()).slice(-2);
  const filename = `${numCli}-${ddmmyy}.xlsx`;

  // Agrupar por GrupoPedido
  const porGrupo = {};
  items.forEach(it => {
    const g = it.p.g || 'OTROS';
    if(!porGrupo[g]) porGrupo[g] = [];
    porGrupo[g].push(it);
  });

  // Crear workbook con SheetJS
  const wb = XLSX.utils.book_new();

  // ===== Hoja 1: RESUMEN (siempre primera, con formato profesional) =====
  const subtotalSinIVA = items.reduce((s, it) => {
    if(!tienePrecio(it.p)) return s;
    return s + it.q * getPrecioPaquete(it.p);
  }, 0);
  const totalConIVA = subtotalSinIVA * 1.16;
  const fechaPedido = today.toLocaleDateString('es-MX', {day:'2-digit', month:'2-digit', year:'numeric'}) +
                      ' ' + today.toLocaleTimeString('es-MX', {hour:'2-digit', minute:'2-digit'});
  const razonSocialCli = cli._comodin
    ? 'Cliente comodín'
    : (cli.rs || cli.nc || '');
  const rfcCli = cli._comodin
    ? ($('cli-rfc').value || '').toUpperCase()
    : (($('cli-rfc').value || cli.rfc || '').toUpperCase());
  const sucursalCli = ($('cli-sucursal').value || '').trim();
  const correoCli = ($('cli-email').value || '').trim();
  const celularCli = $('cli-tel').value || '';

  // Paleta Padcolor para estilos
  const C = {
    blue: '0A3D8F',
    blueLight: 'E8EFFF',
    text: '2A3140',
    textSoft: '6B7385',
    green: '2EA674',
    greenLight: 'E6F7F0',
    white: 'FFFFFF',
    border: 'D8DDE6',
    grey50: 'F8F9FB',
  };
  const thinBorder = {
    top: {style:'thin', color:{rgb:C.border}},
    bottom: {style:'thin', color:{rgb:C.border}},
    left: {style:'thin', color:{rgb:C.border}},
    right: {style:'thin', color:{rgb:C.border}},
  };
  // Estilos reutilizables
  const stTitulo = {
    font:{name:'Calibri', sz:18, bold:true, color:{rgb:C.white}},
    fill:{patternType:'solid', fgColor:{rgb:C.blue}},
    alignment:{horizontal:'center', vertical:'center'},
    border: thinBorder,
  };
  const stSubtitulo = {
    font:{name:'Calibri', sz:10, italic:true, color:{rgb:C.textSoft}},
    fill:{patternType:'solid', fgColor:{rgb:C.grey50}},
    alignment:{horizontal:'center', vertical:'center'},
    border: thinBorder,
  };
  const stSeccion = {
    font:{name:'Calibri', sz:11, bold:true, color:{rgb:C.blue}},
    fill:{patternType:'solid', fgColor:{rgb:C.blueLight}},
    alignment:{horizontal:'left', vertical:'center', indent:1},
    border: thinBorder,
  };
  const stLabel = {
    font:{name:'Calibri', sz:10, bold:true, color:{rgb:C.text}},
    alignment:{horizontal:'left', vertical:'center', indent:1},
    border: thinBorder,
  };
  const stValue = {
    font:{name:'Calibri', sz:10, color:{rgb:C.text}},
    alignment:{horizontal:'left', vertical:'center', indent:1},
    border: thinBorder,
  };
  const stMoney = {
    font:{name:'Calibri', sz:10, color:{rgb:C.text}},
    alignment:{horizontal:'right', vertical:'center', indent:1},
    numFmt:'"$"#,##0.00;[Red]-"$"#,##0.00',
    border: thinBorder,
  };
  const stTotalLabel = {
    font:{name:'Calibri', sz:12, bold:true, color:{rgb:C.green}},
    fill:{patternType:'solid', fgColor:{rgb:C.greenLight}},
    alignment:{horizontal:'left', vertical:'center', indent:1},
    border: thinBorder,
  };
  const stTotalValue = {
    font:{name:'Calibri', sz:13, bold:true, color:{rgb:C.green}},
    fill:{patternType:'solid', fgColor:{rgb:C.greenLight}},
    alignment:{horizontal:'right', vertical:'center', indent:1},
    numFmt:'"$"#,##0.00;[Red]-"$"#,##0.00',
    border: thinBorder,
  };

  // Construir hoja celda por celda (con estilos)
  // Layout dinámico (1-indexed visualmente):
  // r1   : Título
  // r2   : Subtítulo
  // r3   : separador
  // r4   : Sección "DATOS DEL CLIENTE"
  // r5   : Número de cliente
  // r6   : Razón Social
  // r7   : Sucursal
  // r8   : RFC
  // r9   : separador
  // r10  : Sección "DATOS DE CONTACTO"
  // r11  : Correo
  // r12  : Celular
  // r13  : Fecha del pedido
  // r14  : separador
  // r15  : Sección "RESUMEN FINANCIERO"
  // r16  : Subtotal sin IVA
  // r17  : Total con IVA (destacado)
  // — opcional, sólo si aplica situación de exceso de crédito o solicitud activa: —
  // r18  : separador
  // r19  : Sección "EXTENSIÓN DE CRÉDITO"
  // r20-24 : datos del crédito
  // r25  : (opcional) Fecha y status de la solicitud (si ya se tramitó)
  const wsResumen = {};
  const set = (addr, value, style) => {
    const cell = {v: value, t: typeof value === 'number' ? 'n' : 's'};
    if(style) cell.s = style;
    wsResumen[addr] = cell;
  };

  set('A1', 'RESUMEN DEL PRE-PEDIDO', stTitulo); set('B1', '', stTitulo);
  set('A2', 'Padcolor — Papel, Diseño y Color S.A. de C.V.', stSubtitulo); set('B2', '', stSubtitulo);

  set('A4', 'DATOS DEL CLIENTE', stSeccion); set('B4', '', stSeccion);
  set('A5', 'Número de cliente', stLabel);      set('B5', numCli, stValue);
  set('A6', 'Razón Social', stLabel);           set('B6', razonSocialCli, stValue);
  set('A7', 'Nombre o Núm. Sucursal', stLabel); set('B7', sucursalCli, stValue);
  set('A8', 'RFC', stLabel);                    set('B8', rfcCli, stValue);

  set('A10', 'DATOS DE CONTACTO', stSeccion);   set('B10', '', stSeccion);
  set('A11', 'Correo de contacto', stLabel);    set('B11', correoCli, stValue);
  set('A12', 'Celular de contacto', stLabel);   set('B12', celularCli, stValue);
  set('A13', 'Fecha del pedido', stLabel);      set('B13', fechaPedido, stValue);

  set('A15', 'RESUMEN FINANCIERO', stSeccion);  set('B15', '', stSeccion);
  set('A16', 'Subtotal sin IVA', stLabel);      set('B16', subtotalSinIVA, stMoney);
  set('A17', 'Total con IVA (16%)', stTotalLabel); set('B17', totalConIVA, stTotalValue);

  // Merges base
  const mergesBase = [
    {s:{r:0,c:0}, e:{r:0,c:1}},  // A1:B1 - Título
    {s:{r:1,c:0}, e:{r:1,c:1}},  // A2:B2 - Subtítulo
    {s:{r:3,c:0}, e:{r:3,c:1}},  // A4:B4 - Sección 1
    {s:{r:9,c:0}, e:{r:9,c:1}},  // A10:B10 - Sección 2
    {s:{r:14,c:0}, e:{r:14,c:1}},// A15:B15 - Sección 3
  ];
  // Alturas base
  const rowsBase = [
    {hpt:34},  // 1 título
    {hpt:18},  // 2 subtítulo
    {hpt:8},   // 3 separador
    {hpt:22},  // 4 sección
    {hpt:20},  // 5
    {hpt:20},  // 6
    {hpt:20},  // 7
    {hpt:20},  // 8
    {hpt:8},   // 9 separador
    {hpt:22},  // 10 sección
    {hpt:20},  // 11
    {hpt:20},  // 12
    {hpt:20},  // 13
    {hpt:8},   // 14 separador
    {hpt:22},  // 15 sección
    {hpt:22},  // 16
    {hpt:28},  // 17 total destacado
  ];

  let lastRow = 17;

  // ===== Sección PROMOCIÓN 3% + 3% =====
  // Sólo mensaje/instrucción para facturación. NO modifica montos del XLS.
  const promoX = getPromoData();
  if(promoX.real && promoX.activo){
    const stPromoSec = {
      font:{name:'Calibri', sz:11, bold:true, color:{rgb:'FFFFFF'}},
      fill:{patternType:'solid', fgColor:{rgb:'B0008E'}}, // magenta corporativo
      alignment:{horizontal:'left', vertical:'center', indent:1},
      border: thinBorder,
    };
    const stMsgM = {
      font:{name:'Calibri', sz:11, bold:true, color:{rgb: promoX.okM ? C.green : C.textSoft}},
      fill:{patternType:'solid', fgColor:{rgb: promoX.okM ? C.greenLight : 'F4F5F7'}},
      alignment:{horizontal:'left', vertical:'center', indent:1},
      border: thinBorder,
    };
    const stMsgH = {
      font:{name:'Calibri', sz:11, bold:true, color:{rgb: promoX.okH ? C.green : C.textSoft}},
      fill:{patternType:'solid', fgColor:{rgb: promoX.okH ? C.greenLight : 'F4F5F7'}},
      alignment:{horizontal:'left', vertical:'center', indent:1},
      border: thinBorder,
    };
    const pctTxt = (promoX.pct * 100).toFixed(0);
    let r = 19;
    set(`A${r}`, 'PROMOCIÓN 3% + 3%', stPromoSec); set(`B${r}`, '', stPromoSec);
    mergesBase.push({s:{r:r-1,c:0}, e:{r:r-1,c:1}});
    rowsBase.push({hpt:8});  // 18 separador
    rowsBase.push({hpt:22}); // 19 sección
    r++;
    // Muertos
    if(promoX.hasM){
      set(`A${r}`, 'Subtotal Muertos (sin IVA)', stLabel);
      set(`B${r}`, promoX.subM, stMoney);
      rowsBase.push({hpt:20}); r++;
      set(`A${r}`, 'Meta Muertos (sin IVA)', stLabel);
      set(`B${r}`, promoX.objM, stMoney);
      rowsBase.push({hpt:20}); r++;
      const msgM = promoX.okM ? `APLICAR ${pctTxt}% POR MUERTOS` : 'No aplica descuento Muertos (meta no alcanzada)';
      set(`A${r}`, msgM, stMsgM); set(`B${r}`, '', stMsgM);
      mergesBase.push({s:{r:r-1,c:0}, e:{r:r-1,c:1}});
      rowsBase.push({hpt:22}); r++;
    }
    // Halloween
    if(promoX.hasH){
      set(`A${r}`, 'Subtotal Halloween (sin IVA)', stLabel);
      set(`B${r}`, promoX.subH, stMoney);
      rowsBase.push({hpt:20}); r++;
      set(`A${r}`, 'Meta Halloween (sin IVA)', stLabel);
      set(`B${r}`, promoX.objH, stMoney);
      rowsBase.push({hpt:20}); r++;
      const msgH = promoX.okH ? `APLICAR ${pctTxt}% POR HALLOWEEN` : 'No aplica descuento Halloween (meta no alcanzada)';
      set(`A${r}`, msgH, stMsgH); set(`B${r}`, '', stMsgH);
      mergesBase.push({s:{r:r-1,c:0}, e:{r:r-1,c:1}});
      rowsBase.push({hpt:22}); r++;
    }
    // Fila resumen de la regla aplicada (instrucción única para facturación)
    if(promoX.okM || promoX.okH){
      const stBonus = {
        font:{name:'Calibri', sz:11, bold:true, color:{rgb:'FFFFFF'}},
        fill:{patternType:'solid', fgColor:{rgb: promoX.bonus ? '1E8E4A' : 'B0008E'}},
        alignment:{horizontal:'center', vertical:'center'},
        border: thinBorder,
      };
      const resumen = promoX.bonus
        ? `BONUS ${pctTxt}% — alcanzó ambas metas: aplicar ${pctTxt}% a Muertos y Halloween`
        : `Aplicar ${pctTxt}% al segmento con meta alcanzada`;
      set(`A${r}`, resumen, stBonus); set(`B${r}`, '', stBonus);
      mergesBase.push({s:{r:r-1,c:0}, e:{r:r-1,c:1}});
      rowsBase.push({hpt:22}); r++;
    }
    lastRow = r - 1;
  }

  // Sección de extensión de crédito.
  // Aparece SIEMPRE que aplique, sin depender de si el cliente ya tramitó
  // la solicitud. Aplica cuando:
  //   - hay cliente válido y NO es comodín,
  //   - tiene línea de crédito declarada (lc > 0),
  //   - (total del pre-pedido con IVA + saldo actual) > (límite de crédito × 1.30).
  // Los montos se calculan en vivo de cli.lc, cli.sa y el total actual del
  // pre-pedido (no de un snapshot), para que el XLS siempre refleje los
  // números más recientes. Si además state.creditoSolicitado existe, se
  // añade una nota con la fecha en que se tramitó la solicitud.
  if(!cli._comodin){
    const lc = cli.lc || 0;
    const sa = cli.sa || 0;
    const disp = Math.max(0, lc - sa);
    const aplicaCredito = aplicaExcesoCredito(lc, sa, totalConIVA);
    if(aplicaCredito){
      const nuevaLinea = calcularNuevaLineaSugerida(lc, sa, totalConIVA);
      let r = lastRow + 2;               // deja una fila separadora
      rowsBase.push({hpt:8});            // separador
      set(`A${r}`, 'EXTENSIÓN DE CRÉDITO', stSeccion); set(`B${r}`, '', stSeccion);
      mergesBase.push({s:{r:r-1,c:0}, e:{r:r-1,c:1}});
      rowsBase.push({hpt:22}); r++;
      set(`A${r}`, 'Línea de crédito actual', stLabel);      set(`B${r}`, lc, stMoney);   rowsBase.push({hpt:20}); r++;
      set(`A${r}`, 'Saldo actual', stLabel);                 set(`B${r}`, sa, stMoney);   rowsBase.push({hpt:20}); r++;
      set(`A${r}`, 'Crédito disponible', stLabel);           set(`B${r}`, disp, stMoney); rowsBase.push({hpt:20}); r++;
      set(`A${r}`, 'Total del pre-pedido (con IVA)', stLabel); set(`B${r}`, totalConIVA, stMoney); rowsBase.push({hpt:20}); r++;
      set(`A${r}`, 'Nueva línea sugerida', stTotalLabel);    set(`B${r}`, nuevaLinea, stTotalValue); rowsBase.push({hpt:28});
      lastRow = r;
      // Si ya se tramitó la solicitud, añadir nota con la fecha
      if(state.creditoSolicitado && state.creditoSolicitado.fechaSolicitud){
        const f = new Date(state.creditoSolicitado.fechaSolicitud);
        const fechaStr = f.toLocaleDateString('es-MX', {day:'2-digit',month:'2-digit',year:'numeric'}) +
                         ' ' + f.toLocaleTimeString('es-MX', {hour:'2-digit',minute:'2-digit'});
        const stNota = {
          font:{name:'Calibri', sz:9, italic:true, color:{rgb:C.textSoft}},
          alignment:{horizontal:'center', vertical:'center'},
          border: thinBorder,
        };
        r++;
        set(`A${r}`, `Solicitud de extensión tramitada el ${fechaStr}`, stNota); set(`B${r}`, '', stNota);
        mergesBase.push({s:{r:r-1,c:0}, e:{r:r-1,c:1}});
        rowsBase.push({hpt:18});
        lastRow = r;
      }
    }
  }

  // ===== Sección DESCUENTOS GANADOS POR PROMOCIÓN (hasta abajo) =====
  // Tabla de 4 columnas (Meta, Compra, % descuento, Monto Descuento) por
  // segmento + recuadro de observación con el resumen de descuentos obtenidos.
  // Reglas de negocio (idénticas a getPromoData):
  //   - Alcanzar (>=) la meta de un segmento -> 3% sobre lo comprado de ESE segmento.
  //   - Alcanzar AMBAS metas -> se convierte en 6% para AMBOS segmentos.
  // Los montos NO modifican los totales del XLS; son informativos para facturación.
  // La tabla tiene 5 columnas: A=etiqueta y B..E = las 4 cifras
  // (Meta, Compra, % descuento, Monto Descuento).
  let promoWide = false;
  if(promoX.real && promoX.activo){
    promoWide = true;
    const pctTxtD = (promoX.pct * 100).toFixed(0);
    const ganaAlgo = promoX.okM || promoX.okH;
    const montoTotalDesc = (promoX.descM || 0) + (promoX.descH || 0);
    const fmtMX = (n) => '$' + (n||0).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});

    // Estilos locales para la tabla
    const stDescSec = {
      font:{name:'Calibri', sz:11, bold:true, color:{rgb:C.white}},
      fill:{patternType:'solid', fgColor:{rgb:'B0008E'}},
      alignment:{horizontal:'left', vertical:'center', indent:1},
      border: thinBorder,
    };
    const stObs = {
      font:{name:'Calibri', sz:11, bold:true, color:{rgb: ganaAlgo ? C.white : C.text}},
      fill:{patternType:'solid', fgColor:{rgb: ganaAlgo ? '1E8E4A' : 'F4F5F7'}},
      alignment:{horizontal:'center', vertical:'center', wrapText:true},
      border: thinBorder,
    };
    const stHead = {
      font:{name:'Calibri', sz:9, bold:true, color:{rgb:C.white}},
      fill:{patternType:'solid', fgColor:{rgb:C.blue}},
      alignment:{horizontal:'center', vertical:'center'},
      border: thinBorder,
    };
    const stRowLabel = {
      font:{name:'Calibri', sz:10, bold:true, color:{rgb:C.text}},
      alignment:{horizontal:'left', vertical:'center', indent:1},
      border: thinBorder,
    };
    const mkMoney = (ok, strong) => ({
      font:{name:'Calibri', sz:10, bold: !!strong, color:{rgb: ok ? C.green : C.text}},
      alignment:{horizontal:'right', vertical:'center', indent:1},
      numFmt:'"$"#,##0.00;[Red]-"$"#,##0.00',
      border: thinBorder,
    });
    const mkPct = (ok) => ({
      font:{name:'Calibri', sz:10, bold:true, color:{rgb: ok ? C.green : C.textSoft}},
      alignment:{horizontal:'center', vertical:'center'},
      numFmt:'0%',
      border: thinBorder,
    });

    let r = lastRow + 2;            // fila separadora
    rowsBase.push({hpt:8});

    // Encabezado de sección (A:E)
    set(`A${r}`, 'DESCUENTOS GANADOS POR PROMOCIÓN', stDescSec);
    ['B','C','D','E'].forEach(col => set(`${col}${r}`, '', stDescSec));
    mergesBase.push({s:{r:r-1,c:0}, e:{r:r-1,c:4}});
    rowsBase.push({hpt:22}); r++;

    // Renglón 1: observación (gana / no gana) + resumen de descuentos (A:E)
    let obsTxt;
    if(!ganaAlgo){
      obsTxt = 'NO GANA DESCUENTO — aún no se alcanza ninguna meta de la promoción.';
    } else if(promoX.bonus){
      obsTxt = `GANA DESCUENTO — alcanzó ambas metas: ${pctTxtD}% en Muertos y ${pctTxtD}% en Halloween.  ` +
               `Descuento total ganado: ${fmtMX(montoTotalDesc)}`;
    } else {
      const seg = promoX.okM ? 'Muertos' : 'Halloween';
      obsTxt = `GANA DESCUENTO — alcanzó la meta de ${seg}: ${pctTxtD}% sobre ese segmento.  ` +
               `Descuento total ganado: ${fmtMX(montoTotalDesc)}`;
    }
    set(`A${r}`, obsTxt, stObs);
    ['B','C','D','E'].forEach(col => set(`${col}${r}`, '', stObs));
    mergesBase.push({s:{r:r-1,c:0}, e:{r:r-1,c:4}});
    rowsBase.push({hpt:34}); r++;

    // Encabezados de columnas: A vacío, B..E las 4 cifras
    set(`A${r}`, '', stHead);
    set(`B${r}`, 'Meta', stHead);
    set(`C${r}`, 'Compra', stHead);
    set(`D${r}`, '% Descuento', stHead);
    set(`E${r}`, 'Monto Descuento', stHead);
    rowsBase.push({hpt:18}); r++;

    // Renglón 2: Descuento por Muertos
    set(`A${r}`, 'Descuento por Muertos', stRowLabel);
    set(`B${r}`, promoX.hasM ? promoX.objM : 0, mkMoney(false));
    set(`C${r}`, promoX.subM, mkMoney(promoX.okM));
    set(`D${r}`, promoX.okM ? promoX.pct : 0, mkPct(promoX.okM));
    set(`E${r}`, promoX.descM || 0, mkMoney(promoX.okM, true));
    rowsBase.push({hpt:20}); r++;

    // Renglón 3: Descuento por Halloween
    set(`A${r}`, 'Descuento por Halloween', stRowLabel);
    set(`B${r}`, promoX.hasH ? promoX.objH : 0, mkMoney(false));
    set(`C${r}`, promoX.subH, mkMoney(promoX.okH));
    set(`D${r}`, promoX.okH ? promoX.pct : 0, mkPct(promoX.okH));
    set(`E${r}`, promoX.descH || 0, mkMoney(promoX.okH, true));
    rowsBase.push({hpt:20});

    lastRow = r;
  }

  // Rango de la hoja (dinámico). La sección de descuentos amplía a 5 columnas.
  const lastColLetter = promoWide ? 'E' : 'B';
  wsResumen['!ref'] = 'A1:' + lastColLetter + lastRow;
  wsResumen['!merges'] = mergesBase;
  // Anchos de columnas (C..E sólo se usan en la sección de descuentos)
  wsResumen['!cols'] = promoWide
    ? [{wch:30}, {wch:16}, {wch:16}, {wch:13}, {wch:18}]
    : [{wch:30}, {wch:42}];
  // Alturas
  wsResumen['!rows'] = rowsBase;

  XLSX.utils.book_append_sheet(wb, wsResumen, 'Resumen');

  // ===== Hojas por grupo =====
  // Orden: TODA OCASIÓN, PRECIO ESPECIAL, ESCOLAR, etc.
  const orden = ['MUERTOS','HALLOWEEN','PRECIO ESPECIAL','OTROS'];
  const grupos = Object.keys(porGrupo).sort((a,b) => {
    const ia = orden.indexOf(a); const ib = orden.indexOf(b);
    return (ia===-1?99:ia) - (ib===-1?99:ib);
  });

  grupos.forEach(g => {
    // Ordenar de mayor a menor cantidad pedida (en piezas)
    const lista = [...porGrupo[g]].sort((a,b) => (b.q*b.p.m) - (a.q*a.p.m));
    const rows = [['Código','Descripción','Cantidad','Precio Unitario','Subtotal sin IVA']];
    lista.forEach(it => {
      const piezas = it.q * it.p.m;
      const precioPieza = tienePrecio(it.p) ? getPrecioPieza(it.p) : 0;
      const subSinIva  = piezas * precioPieza;
      rows.push([it.p.c, it.p.d, piezas, precioPieza, subSinIva]);
    });
    const ws = XLSX.utils.aoa_to_sheet(rows);
    // Formato moneda y header en negrita
    const totalRows = rows.length;
    const headerStyle = {
      font:{name:'Calibri', sz:10, bold:true, color:{rgb:'FFFFFF'}},
      fill:{patternType:'solid', fgColor:{rgb:'0A3D8F'}},
      alignment:{horizontal:'center', vertical:'center'},
      border:{
        top:{style:'thin',color:{rgb:'D8DDE6'}},
        bottom:{style:'thin',color:{rgb:'D8DDE6'}},
        left:{style:'thin',color:{rgb:'D8DDE6'}},
        right:{style:'thin',color:{rgb:'D8DDE6'}},
      },
    };
    const moneyFmt = '"$"#,##0.00;[Red]-"$"#,##0.00';
    // Aplicar estilos a la cabecera (fila 1)
    ['A1','B1','C1','D1','E1'].forEach(addr => {
      if(ws[addr]) ws[addr].s = headerStyle;
    });
    // Aplicar formato moneda a las columnas D y E para las filas de datos
    for(let r = 2; r <= totalRows; r++){
      const dAddr = 'D' + r;
      const eAddr = 'E' + r;
      if(ws[dAddr]){ ws[dAddr].t = 'n'; ws[dAddr].z = moneyFmt; ws[dAddr].s = {numFmt: moneyFmt, alignment:{horizontal:'right'}}; }
      if(ws[eAddr]){ ws[eAddr].t = 'n'; ws[eAddr].z = moneyFmt; ws[eAddr].s = {numFmt: moneyFmt, alignment:{horizontal:'right'}}; }
    }
    // Anchos sugeridos
    ws['!cols'] = [{wch:14},{wch:50},{wch:11},{wch:15},{wch:17}];
    // Altura del header
    ws['!rows'] = [{hpt:22}];
    // Limitar nombre de hoja a 31 chars (Excel limit)
    let sheetName = g.length > 31 ? g.substring(0,28)+'...' : g;
    sheetName = sheetName.replace(/[\[\]\*\?\/\\:]/g,'_');
    XLSX.utils.book_append_sheet(wb, ws, sheetName);
  });

  // Descargar
  XLSX.writeFile(wb, filename);

  // Mensaje
  const ag = state.agente;
  let mensaje;
  if(cli._comodin){
    mensaje = `Tu pre-pedido se descargó como <strong>${filename}</strong> en tu carpeta de Descargas.<br><br>
      Envíalo por correo a <strong>Asistente de Ventas</strong>: <a href="mailto:auxventas@padcolor.com">auxventas@padcolor.com</a>.`;
  } else {
    const waFmt = formatWhatsApp(ag.wa);
    mensaje = `Tu pre-pedido se descargó como <strong>${filename}</strong> en tu carpeta de Descargas.<br><br>
      Envíalo a <strong>${ag.nom}</strong> por correo a <a href="mailto:${ag.mail}">${ag.mail}</a>${waFmt ? ' o por WhatsApp a <strong>'+waFmt+'</strong>':''}.`;
  }
  showModal('Pre-pedido generado ✓', `<div style="line-height:1.6">${mensaje}</div>`);

  // NO se limpia el carrito automáticamente. El usuario puede modificar el
  // carrito y volver a Finalizar para regenerar el XLS; o presionar
  // "Nuevo Pedido" para resetear todo y empezar desde cero.
  mostrarBotonNuevoPedido();
}

// Mostrar el botón "Nuevo Pedido" en el footer del carrito, junto con un
// pequeño banner verde de confirmación arriba del botón Finalizar.
function mostrarBotonNuevoPedido(){
  const btn = $('btn-new-order');
  if(btn) btn.style.display = 'block';
  const banner = $('post-finalize-banner');
  if(banner) banner.style.display = 'block';
}

// Reset PARCIAL: limpia carrito, snapshot de crédito y UI de finalización,
// pero CONSERVA el cliente validado, RFC, Razón Social, Sucursal, Correo y
// Celular. Pensado para que el mismo cliente capture otro pre-pedido sin
// volver a teclear su identificación.
// Para borrar TODO (cambiar de cliente) basta con que el usuario edite el
// campo de número de cliente — el flujo de validación se ocupa del reset.
function nuevoPedido(){
  // Carrito y snapshot de crédito
  state.carrito = {};
  state.creditoSolicitado = null;

  // Ocultar botón Nuevo Pedido y banner de confirmación
  const btn = $('btn-new-order');
  if(btn) btn.style.display = 'none';
  const banner = $('post-finalize-banner');
  if(banner) banner.style.display = 'none';

  // Re-render del carrito (vacío) y del catálogo (para refrescar el estado
  // de existencias/precios — el cliente sigue validado así que los botones
  // "Agregar" permanecen habilitados). Recalcular el botón Finalizar para
  // que vuelva a deshabilitarse hasta tener al menos 1 producto.
  renderCarrito();
  renderProductos();
  actualizarFinalizar();

  toast('Listo para un nuevo pre-pedido (mismo cliente)', 'success', 2200);
}

// ===========================================================================
// SOLICITUD DE AUMENTO DE LÍNEA DE CRÉDITO
// Flujo completo: form + adjuntos + pagaré + expediente consolidado en PDF
// Solo se admite firma física: cliente descarga pagaré, lo imprime, lo firma,
// lo sube como imagen.
// ===========================================================================

// Estados de la República Mexicana (para selects de dirección)
const ESTADOS_MX = [
  'Aguascalientes','Baja California','Baja California Sur','Campeche','Chiapas',
  'Chihuahua','Ciudad de México','Coahuila','Colima','Durango','Estado de México',
  'Guanajuato','Guerrero','Hidalgo','Jalisco','Michoacán','Morelos','Nayarit',
  'Nuevo León','Oaxaca','Puebla','Querétaro','Quintana Roo','San Luis Potosí',
  'Sinaloa','Sonora','Tabasco','Tamaulipas','Tlaxcala','Veracruz','Yucatán','Zacatecas'
];
function optionsEstados(selected){
  return '<option value="">— Selecciona —</option>' +
    ESTADOS_MX.map(e => `<option value="${e}"${e === selected ? ' selected' : ''}>${e}</option>`).join('');
}

