      <div class="credit-field">
        <label>País <span class="req">*</span></label>
        <input type="text" class="credit-input" id="cred-sol-pais" value="México">
      </div>
    </div>
    <div class="credit-grid-2">
      <div class="credit-field">
        <label>INE solicitante - frente <span class="req">*</span></label>
        <input type="file" class="credit-input" id="cred-ine-frente" accept="image/*,application/pdf">
      </div>
      <div class="credit-field">
        <label>INE solicitante - reverso <span class="req">*</span></label>
