      <button class="btn-primary" id="btn-cred-submit">Generar y descargar solicitud</button>
    </div>
  `;

  showModal('Solicitud de aumento de línea de crédito', html, null, {wide: true});

  // Listener tel del firmante: formato (XX) XXXX XXXX
  $('cred-sol-tel').addEventListener('input', e => {
    e.target.value = formatPhoneSpaces(e.target.value);
  });

  // Botón submit
  $('btn-cred-submit').addEventListener('click', procesarSolicitudCredito);

  // Botón descargar pagaré en blanco
  $('btn-descargar-pagare-blanco').addEventListener('click', async () => {
    await generarYDescargarPagare();
  });

  // Selector tipo de persona (moral / física)
  const aplicarTipo = (tipo) => {
    state.tipoPersona = tipo;
    $('tipo-moral').classList.toggle('selected', tipo === 'moral');
    $('tipo-fisica').classList.toggle('selected', tipo === 'fisica');
    // El poder/acta constitutiva sólo aplica a persona moral
    const pw = $('poder-wrap');
    if(pw) pw.style.display = tipo === 'moral' ? '' : 'none';
    if(tipo === 'fisica'){ const f = $('cred-poder'); if(f) f.value = ''; }
  };
  $('tipo-moral').addEventListener('click', () => aplicarTipo('moral'));
  $('tipo-fisica').addEventListener('click', () => aplicarTipo('fisica'));
  aplicarTipo(state.tipoPersona || 'moral');
}

// ---- Helpers del módulo de crédito ----
function creditoCalcularTotal(){
  return Object.values(state.carrito).reduce((s, it) => {
    return s + (tienePrecio(it.p) ? it.q * getPrecioPaquete(it.p) * 1.16 : 0);
  }, 0);
}
// Calcula la "Nueva línea de crédito sugerida" con la fórmula:
//   Nueva = Total con IVA − Crédito disponible + Línea actual
// El resultado se redondea HACIA ARRIBA al siguiente múltiplo de $1,000
// (Math.ceil) para que la cifra final siempre sea un número limpio.
// Económicamente equivale a "la línea mínima que cubre el saldo pendiente
// del cliente MÁS este nuevo pre-pedido" — porque Línea − Disponible = Saldo
// en condiciones normales (Saldo ≤ Línea); si el cliente ya está sobregirado
// (Saldo > Línea), Disponible se hace 0 y la fórmula degrada a Total + Línea.
// Esta es la única fuente de verdad para "Nueva línea sugerida" — se usa en
// el XLS Resumen, en el modal de solicitud, en el pagaré y en la carátula
// del expediente PDF para asegurar que las cuatro vistas muestren la misma
// cifra exacta.
const REDONDEO_LINEA_CREDITO = 1000;
function calcularNuevaLineaSugerida(lc, sa, totalConIVA){
  const _lc = Number(lc) || 0;
  const _sa = Number(sa) || 0;
  const _tot = Number(totalConIVA) || 0;
  const disp = Math.max(0, _lc - _sa);
  const cruda = _tot - disp + _lc;
  if(cruda <= 0) return 0;
  return Math.ceil(cruda / REDONDEO_LINEA_CREDITO) * REDONDEO_LINEA_CREDITO;
}
// Factor de tolerancia sobre el límite de crédito antes de disparar el flujo
// de incremento de línea. El botón / bloque de "Tramita tu incremento express"
// y la sección EXTENSIÓN DE CRÉDITO del XLS aparecen únicamente cuando:
//   (Total del pre-pedido con IVA + Saldo actual) > (Límite de crédito × 1.30)
// Es la única fuente de verdad de esta condición; cambiar FACTOR_EXCESO_CREDITO
// la actualiza en todos los lugares donde aplica.
const FACTOR_EXCESO_CREDITO = 1.30;
function aplicaExcesoCredito(lc, sa, totalConIVA){
  const _lc = Number(lc) || 0;
  const _sa = Number(sa) || 0;
  const _tot = Number(totalConIVA) || 0;
  if(_lc <= 0) return false;
  return (_tot + _sa) > (_lc * FACTOR_EXCESO_CREDITO);
}
function formatPhoneInput(value){
  const d = (value||'').replace(/\D/g,'').slice(0, 10);
  if(d.length === 0) return '';
  if(d.length <= 2) return '(' + d;
  if(d.length <= 6) return '(' + d.slice(0,2) + ') ' + d.slice(2);
  return '(' + d.slice(0,2) + ') ' + d.slice(2,6) + '-' + d.slice(6);
}
// Formato (XX) XXXX XXXX — con espacios, para el teléfono móvil del firmante
function formatPhoneSpaces(value){
  const d = (value||'').replace(/\D/g,'').slice(0, 10);
  if(d.length === 0) return '';
  if(d.length <= 2) return '(' + d;
  if(d.length <= 6) return '(' + d.slice(0,2) + ') ' + d.slice(2);
  return '(' + d.slice(0,2) + ') ' + d.slice(2,6) + ' ' + d.slice(6);
}
// Arma una dirección completa legible a partir de sus partes
function armarDireccion(p){
  let s = (p.calle || '').trim();
  if(p.numext) s += ` #${p.numext.trim()}`;
  if(p.numint && p.numint.trim()) s += ` Int. ${p.numint.trim()}`;
  if(p.colonia) s += `, Col. ${p.colonia.trim()}`;
  if(p.ciudad) s += `, ${p.ciudad.trim()}`;
  if(p.estado) s += `, ${p.estado.trim()}`;
  if(p.cp) s += `, C.P. ${p.cp.trim()}`;
  if(p.pais) s += `, ${p.pais.trim()}`;
  return s;
}
function generarFechaArchivoCredito(){
  const d = new Date();
  return `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
}
function descargarPDF(bytes, nombre){
  const blob = new Blob([bytes], {type: 'application/pdf'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = nombre;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

// ---- Generación del pagaré (siempre sin firmas: cliente lo imprime y firma) ----
async function generarYDescargarPagare(){
  try {
    const datos = recolectarDatosPagare();
    const pdfBytes = await generarPagarePDF(datos);
    descargarPDF(pdfBytes, `Pagare_${state.cliente.n}_${generarFechaArchivoCredito()}.pdf`);
    toast('Pagaré descargado', 'success');
  } catch(e){
    console.error(e);
    toast('Error al generar pagaré: ' + e.message, 'error');
  }
}

function recolectarDatosPagare(){
  const total = creditoCalcularTotal();
  // Monto del pagaré = Nueva línea sugerida (la misma cifra que ve el cliente
  // en el modal y que aparece en el XLS y en la carátula del expediente).
  const monto = calcularNuevaLineaSugerida(state.cliente.lc||0, state.cliente.sa||0, total);
  const fecha = new Date();
  const meses = ['enero','febrero','marzo','abril','mayo','junio',
    'julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const fechaExpStr = `${fecha.getDate()} de ${meses[fecha.getMonth()]} de ${fecha.getFullYear()}`;
  // Vencimiento: exactamente un año posterior a la fecha de la solicitud
  const venc = new Date(fecha.getFullYear() + 1, fecha.getMonth(), fecha.getDate());
  const fechaVencStr = `${venc.getDate()} de ${meses[venc.getMonth()]} de ${venc.getFullYear()}`;

  // Recolectar datos del formulario (pueden no existir si el modal no está abierto)
  const v = id => { const el = $(id); return el ? el.value.trim() : ''; };
  // La razón social / nombre de la persona moral o física proviene SIEMPRE del
  // campo capturado en la solicitud (no del catálogo de clientes).
  const razonSocial = v('cred-razon-social') || '__________________';
  const solNombreCompleto = [v('cred-sol-nombres'), v('cred-sol-paterno'), v('cred-sol-materno')]
    .filter(Boolean).join(' ');
  const domicilioSolicitante = armarDireccion({
    calle: v('cred-sol-calle'), numext: v('cred-sol-numext'), numint: v('cred-sol-numint'),
    colonia: v('cred-sol-colonia'), ciudad: v('cred-sol-ciudad'), estado: v('cred-sol-estado'),
    cp: v('cred-sol-cp'), pais: v('cred-sol-pais'),
  }) || state.cliente.dom || '(Domicilio no registrado)';
  const avalNombreCompleto = [v('cred-aval-nombres'), v('cred-aval-paterno'), v('cred-aval-materno')]
    .filter(Boolean).join(' ');
  const domicilioAval = armarDireccion({
    calle: v('cred-aval-calle'), numext: v('cred-aval-numext'), numint: v('cred-aval-numint'),
    colonia: v('cred-aval-colonia'), ciudad: v('cred-aval-ciudad'), estado: v('cred-aval-estado'),
    cp: v('cred-aval-cp'), pais: v('cred-aval-pais'),
  });

  return {
    tipoPersona: state.tipoPersona,
    lugarExpedicion: 'Zapopan, Jalisco',
    fechaExpedicion: fechaExpStr,
    beneficiario: 'Papel, Diseño y Color S.A. de C.V.',
    domicilioBeneficiario: 'Avenida del Tigre 2005, Col. Hogares de Nuevo México, Zapopan, Jalisco, C.P. 45138',
    // Para el cuerpo del pagaré: la persona moral/física es el deudor
    deudor: razonSocial,
    razonSocial,
    solNombreCompleto: solNombreCompleto || '__________________',
    domicilioDeudor: domicilioSolicitante,
    rfcDeudor: ($('cli-rfc').value || state.cliente.rfc || '').toUpperCase().trim(),
    monto,
    montoFmt: monto.toLocaleString('es-MX', {minimumFractionDigits: 2, maximumFractionDigits: 2}),
    montoLetra: numeroALetras(monto),
    fechaVencimiento: fechaVencStr,
    tasaMoratoria: '2',
    ciudadJurisdiccion: 'Zapopan, Jalisco',
    avalNombre: avalNombreCompleto || '__________________',
    avalDomicilio: domicilioAval || '__________________',
  };
}

// ===== Membrete corporativo de los PDF (pagaré, carátula y adjuntos) =====
// Cada página del expediente lleva el logo Padcolor centrado arriba, una línea
// separadora de header, una de footer y el pie corporativo con la dirección y
// teléfono de la empresa. Esto homologa la presentación de todos los PDF.
const MBR = {
  W: 612, H: 792, MX: 48,        // tamaño carta y márgenes
  // El logo se ajusta DENTRO de una caja (alto y ancho máximos), preservando
  // su proporción y centrado. Así nunca se sale del cuadre ni se corta, sin
  // importar la proporción del archivo de logo que se cargue.
  LOGO_BOX_W: 150,               // ancho máximo de la caja del logo
  LOGO_BOX_H: 54,                // alto máximo de la caja del logo
  LOGO_TOP: 24,                  // margen desde el borde superior a la caja
  LOGO_GAP: 12,                  // separación entre el logo y la línea del header
  FTR_Y: 54,                     // línea separadora del footer
  BODY_BTM: 64,                  // último Y usable de contenido
};
// Geometría derivada del header (se calcula una vez):
//   HDR_Y    = Y de la línea separadora del header
//   BODY_TOP = primer Y usable de contenido (justo bajo la línea)
MBR.HDR_Y = MBR.H - MBR.LOGO_TOP - MBR.LOGO_BOX_H - MBR.LOGO_GAP;
MBR.BODY_TOP = MBR.HDR_Y - 8;

async function prepMbr(doc){
  const { StandardFonts } = PDFLib;
  const fn  = await doc.embedFont(StandardFonts.Helvetica);
  const fnB = await doc.embedFont(StandardFonts.HelveticaBold);
  // El logo se toma del <img> del header de la página (data URI JPEG).
  const logoEl = document.querySelector('.logo-mark');
  const src = logoEl ? logoEl.src : '';
  let logo = null;
  if(src && src.indexOf(',') !== -1){
    const b64 = src.split(',')[1];
    const raw = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
    try { logo = await doc.embedJpg(raw); }
    catch(e){ try { logo = await doc.embedPng(raw); } catch(_){ logo = null; } }
  }
  return { fn, fnB, logo };
}

function drawMbr(page, { fn, logo }){
  const { rgb } = PDFLib;
  const { W, H, MX, LOGO_BOX_W, LOGO_BOX_H, LOGO_TOP, HDR_Y, FTR_Y } = MBR;
  const gray = rgb(.55,.55,.55), grayT = rgb(.4,.4,.4);
  // Logo: ajustado DENTRO de la caja (alto y ancho máximos), preservando
  // proporción, centrado horizontalmente y anclado por arriba. El factor de
  // escala toma el menor entre ajustar por ancho y por alto, de modo que el
  // logo nunca rebase la caja ni se recorte, sea cual sea su proporción.
  if(logo){
    const scale = Math.min(LOGO_BOX_W / logo.width, LOGO_BOX_H / logo.height);
    const lW = logo.width * scale;
    const lH = logo.height * scale;
    const lx = (W - lW) / 2;                       // centrado horizontal
    const ly = H - LOGO_TOP - lH;                  // anclado al margen superior
    page.drawImage(logo, {x: lx, y: ly, width: lW, height: lH});
  }
  // Línea header y footer
  page.drawLine({start:{x:MX,y:HDR_Y}, end:{x:W-MX,y:HDR_Y}, thickness:.75, color:gray});
  page.drawLine({start:{x:MX,y:FTR_Y}, end:{x:W-MX,y:FTR_Y}, thickness:.75, color:gray});
  // Pie corporativo
  const f1 = 'Papel, Diseño y Color S.A. de C.V.';
  const f2 = 'Calle Av. del tigre 2005 Col. Hogares de Nuevo México, Zapopan, Jalisco, 45138  Tel: (33) 3365-1230';
  page.drawText(f1, {x:(W - fn.widthOfTextAtSize(f1,8.5))/2, y:40, font:fn, size:8.5, color:grayT});
  page.drawText(f2, {x:(W - fn.widthOfTextAtSize(f2,7))/2,   y:27, font:fn, size:7,   color:grayT});
}

async function generarPagarePDF(d){
  const { PDFDocument } = PDFLib;
  const pdfDoc = await PDFDocument.create();
  const mbr = await prepMbr(pdfDoc);
  const { fn: font, fnB: fontBold } = mbr;
  const { W, MX, BODY_TOP, BODY_BTM } = MBR;
  const cW = W - 2*MX;
  const page = pdfDoc.addPage([W, MBR.H]);
  drawMbr(page, mbr);

  // Encabezado (sin folio), dentro del área del membrete
  let yTit = BODY_TOP - 10;
  page.drawText('PAGARÉ', {x: (W - fontBold.widthOfTextAtSize('PAGARÉ', 20))/2, y: yTit, font: fontBold, size: 20});
  yTit -= 18;
  const amtTxt = `Bueno por: $${d.montoFmt} M.N.`;
  page.drawText(amtTxt, {x: W - MX - fontBold.widthOfTextAtSize(amtTxt, 11), y: yTit, font: fontBold, size: 11});

  // Cuerpo
  const cuerpo = `En ${d.lugarExpedicion}, a ${d.fechaExpedicion}.

Por el presente pagaré, ${d.razonSocial}, con domicilio en ${d.domicilioDeudor} y RFC ${d.rfcDeudor}, me obligo incondicionalmente a pagar a la orden de ${d.beneficiario}, con domicilio en ${d.domicilioBeneficiario}, la cantidad de $${d.montoFmt} M.N. (${d.montoLetra}), en ${d.domicilioBeneficiario}, el día ${d.fechaVencimiento}.

Esta cantidad la recibí a mi entera satisfacción.

En caso de mora, este pagaré causará un interés moratorio de ${d.tasaMoratoria}% mensual sobre el monto adeudado, computado por días naturales, a partir del día siguiente al vencimiento y hasta el día de su pago total.

Para el caso de incumplimiento en el pago de este pagaré, el suscriptor se obliga a pagar gastos y costas de cobranza, incluyendo honorarios legales.

El presente documento es título ejecutivo conforme a la Ley General de Títulos y Operaciones de Crédito.

El deudor y el aval se someten expresamente a la jurisdicción de los tribunales de ${d.ciudadJurisdiccion}, renunciando a cualquier otro fuero que pudiera corresponderles por razón de su domicilio presente o futuro. El aval responde solidariamente como obligado principal.`;

  let y = BODY_TOP - 50;
  const SIG_RESERVE = 110; // espacio reservado para los bloques de firma
  const lineas = wordWrap(cuerpo, font, 10, cW);
  for(const ln of lineas){
    if(y < BODY_BTM + SIG_RESERVE) break;
    page.drawText(ln, {x: MX, y, font, size: 10});
    y -= 14;
  }

  // ---- Bloque de firmas ----
  // Dos columnas. El contenido del bloque DEUDOR depende del tipo de persona:
  //   - Persona física: nombre del solicitante, RFC, domicilio → "Firma del Deudor".
  //   - Persona moral: razón social, RFC, domicilio, "representada por …",
  //     "Apoderado Legal" → "Firma del Apoderado Legal".
  // Bajo "AVAL": nombre completo y domicilio del aval.
  const colDeudorX = MX;
  const colAvalX = MX + Math.floor(cW/2) + 10;
  const colWidth = Math.floor(cW/2) - 10;

  const escribirBloque = (x, titulo, lineasDatos, yStart) => {
    let yy = yStart;
    page.drawText(titulo, {x, y: yy, font: fontBold, size: 10});
    yy -= 14;
    for(const item of lineasDatos){
      const wrapped = wordWrap(item, font, 8.5, colWidth);
      for(const wl of wrapped){
        page.drawText(wl, {x, y: yy, font, size: 8.5});
        yy -= 12;
      }
    }
    return yy;
  };

  const esFisica = d.tipoPersona === 'fisica';
  const datosDeudor = esFisica
    ? [ d.solNombreCompleto, `RFC: ${d.rfcDeudor}`, `Domicilio: ${d.domicilioDeudor}` ]
    : [ d.razonSocial, `RFC: ${d.rfcDeudor}`, `Domicilio: ${d.domicilioDeudor}`,
        `representada por ${d.solNombreCompleto}`, `Apoderado Legal` ];
  const datosAval = [
    d.avalNombre,
    `Domicilio: ${d.avalDomicilio}`,
  ];

  const bloqueYStart = Math.max(BODY_BTM + SIG_RESERVE - 10, y - 16);
  const yFinDeudor = escribirBloque(colDeudorX, 'DEUDOR', datosDeudor, bloqueYStart);
  const yFinAval = escribirBloque(colAvalX, 'AVAL', datosAval, bloqueYStart);

  // La línea de firma va debajo del bloque más bajo de las dos columnas.
  const yLinea = Math.min(yFinDeudor, yFinAval) - 24;
  page.drawLine({start: {x: colDeudorX, y: yLinea}, end: {x: colDeudorX + 180, y: yLinea}, thickness: 0.5});
  page.drawText(esFisica ? 'Firma del Deudor' : 'Firma del Apoderado Legal',
    {x: colDeudorX + (esFisica ? 30 : 10), y: yLinea - 13, font, size: 9});

  page.drawLine({start: {x: colAvalX, y: yLinea}, end: {x: colAvalX + 180, y: yLinea}, thickness: 0.5});
  page.drawText('Firma del Aval', {x: colAvalX + 40, y: yLinea - 13, font, size: 9});

  return await pdfDoc.save();
}

function wordWrap(text, font, size, maxWidth){
  const lineas = [];
  const parrafos = text.split('\n');
  for(const para of parrafos){
    if(!para.trim()){ lineas.push(''); continue; }
    const words = para.split(' ');
    let cur = '';
    for(const w of words){
      const test = cur ? cur + ' ' + w : w;
      const width = font.widthOfTextAtSize(test, size);
      if(width > maxWidth && cur){
        lineas.push(cur);
        cur = w;
      } else {
        cur = test;
      }
    }
    if(cur) lineas.push(cur);
  }
  return lineas;
}

// ---- Conversión número a letras (PESOS) ----
function numeroALetras(n){
  const entero = Math.floor(n);
  const cents = Math.round((n - entero) * 100);
  return `${enteroALetras(entero)} PESOS ${String(cents).padStart(2, '0')}/100 M.N.`;
}

function enteroALetras(n){
  if(n === 0) return 'CERO';
  const unidades = ['', 'UN', 'DOS', 'TRES', 'CUATRO', 'CINCO', 'SEIS', 'SIETE', 'OCHO', 'NUEVE'];
  const especiales = ['DIEZ', 'ONCE', 'DOCE', 'TRECE', 'CATORCE', 'QUINCE', 'DIECISÉIS', 'DIECISIETE', 'DIECIOCHO', 'DIECINUEVE'];
  const decenas = ['', '', 'VEINTI', 'TREINTA', 'CUARENTA', 'CINCUENTA', 'SESENTA', 'SETENTA', 'OCHENTA', 'NOVENTA'];
  const centenas = ['', 'CIENTO', 'DOSCIENTOS', 'TRESCIENTOS', 'CUATROCIENTOS', 'QUINIENTOS', 'SEISCIENTOS', 'SETECIENTOS', 'OCHOCIENTOS', 'NOVECIENTOS'];

  function leer3(x){
    if(x === 0) return '';
    if(x === 100) return 'CIEN';
    let r = '';
    const c = Math.floor(x / 100);
    const dy = x % 100;
    const dec = Math.floor(dy / 10);
    const u = dy % 10;
    if(c) r += centenas[c] + ' ';
    if(dy >= 10 && dy <= 19) r += especiales[dy - 10];
    else if(dec === 2) r += (u === 0 ? 'VEINTE' : 'VEINTI' + unidades[u]);
    else if(dec > 2){
      r += decenas[dec];
      if(u) r += ' Y ' + unidades[u];
    } else if(u) r += unidades[u];
    return r.trim();
  }

  let res = '';
  const millones = Math.floor(n / 1000000);
  const miles = Math.floor((n % 1000000) / 1000);
  const resto = n % 1000;
  if(millones){
    res += (millones === 1 ? 'UN MILLÓN' : leer3(millones) + ' MILLONES') + ' ';
  }
  if(miles){
    if(miles === 1) res += 'MIL ';
    else res += leer3(miles) + ' MIL ';
  }
  if(resto) res += leer3(resto);
  return res.trim().replace(/\s+/g, ' ');
}

// ---- Procesar solicitud (generar expediente consolidado) ----
async function procesarSolicitudCredito(){
  const errEl = $('cred-error');
  errEl.textContent = '';
  const v = id => { const el = $(id); return el ? el.value.trim() : ''; };

  // ----- Datos del solicitante -----
  const razonSocial = v('cred-razon-social');
  const solNombres = v('cred-sol-nombres');
  const solPaterno = v('cred-sol-paterno');
  const solEmail = v('cred-sol-email');
  const solTel = v('cred-sol-tel').replace(/\D/g, '');
  const solCalle = v('cred-sol-calle');
  const solNumext = v('cred-sol-numext');
  const solColonia = v('cred-sol-colonia');
  const solCiudad = v('cred-sol-ciudad');
  const solEstado = v('cred-sol-estado');
  const solCP = v('cred-sol-cp');
  const solPais = v('cred-sol-pais');

  if(!razonSocial){ errEl.textContent = 'Captura el nombre completo de la persona moral o física'; return; }
  if(!solNombres || !solPaterno){ errEl.textContent = 'Captura nombres y apellido paterno del solicitante'; return; }
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(solEmail)){ errEl.textContent = 'Captura un correo electrónico válido del firmante'; return; }
  if(solTel.length !== 10){ errEl.textContent = 'El teléfono móvil del firmante debe tener 10 dígitos'; return; }
  if(!solCalle || !solNumext || !solColonia || !solCiudad || !solEstado || !solCP || !solPais){
    errEl.textContent = 'Completa todos los campos de la dirección del solicitante (incluido el estado)';
    return;
  }

  // ----- Datos del aval -----
  const avalNombres = v('cred-aval-nombres');
  const avalPaterno = v('cred-aval-paterno');
  const avalCalle = v('cred-aval-calle');
  const avalNumext = v('cred-aval-numext');
  const avalColonia = v('cred-aval-colonia');
  const avalCiudad = v('cred-aval-ciudad');
  const avalEstado = v('cred-aval-estado');
  const avalCP = v('cred-aval-cp');
  const avalPais = v('cred-aval-pais');

  if(!avalNombres || !avalPaterno){ errEl.textContent = 'Captura nombres y apellido paterno del aval'; return; }
  if(!avalCalle || !avalNumext || !avalColonia || !avalCiudad || !avalEstado || !avalCP || !avalPais){
    errEl.textContent = 'Completa todos los campos de la dirección del aval (incluido el estado)';
    return;
  }

  // ----- Adjuntos requeridos -----
  const ineFr = $('cred-ine-frente').files[0];
  const ineRv = $('cred-ine-reverso').files[0];
  const compr = $('cred-comprobante').files[0];
  const avalIneFr = $('cred-aval-ine-frente').files[0];
  const avalIneRv = $('cred-aval-ine-reverso').files[0];
  const avalCompr = $('cred-aval-comprobante').files[0];
  const poderFile = $('cred-poder') ? $('cred-poder').files[0] : null;

  if(!ineFr || !ineRv || !compr){
    errEl.textContent = 'Adjunta INE frente, reverso y comprobante de domicilio del solicitante';
    return;
  }
  if(state.tipoPersona === 'moral' && !poderFile){
    errEl.textContent = 'Adjunta el poder del representante (acta constitutiva) para persona moral';
    return;
  }
  if(!avalIneFr || !avalIneRv || !avalCompr){
    errEl.textContent = 'Adjunta INE frente, reverso y comprobante de domicilio del aval';
    return;
  }

  const pagareFirmadoFile = $('cred-pagare-firmado').files[0];
  if(!pagareFirmadoFile){
    errEl.textContent = 'Sube el pagaré firmado (foto o escaneo)';
    return;
  }

  // Nombres completos para la carátula
  const solNombreCompleto = [solNombres, solPaterno, v('cred-sol-materno')].filter(Boolean).join(' ');
  const avalNombreCompleto = [avalNombres, avalPaterno, v('cred-aval-materno')].filter(Boolean).join(' ');

  // Generar expediente consolidado
  const btn = $('btn-cred-submit');
  const txtOriginal = btn.textContent;
  btn.textContent = 'Generando…';
  btn.disabled = true;

  try {
    const componentes = [];

    // 1. Carátula
    componentes.push(await generarCaratulaPDF({
      razonSocial,
      solNombreCompleto,
      solEmail,
      solTel: formatPhoneSpaces(solTel),
      avalNombreCompleto,
    }));

    // 2. Adjuntos del solicitante
    componentes.push(await imageOrPdfToPdfBytes(ineFr, 'INE solicitante - frente'));
    componentes.push(await imageOrPdfToPdfBytes(ineRv, 'INE solicitante - reverso'));
    componentes.push(await imageOrPdfToPdfBytes(compr, 'Comprobante de domicilio'));
    if(state.tipoPersona === 'moral' && poderFile){
      componentes.push(await imageOrPdfToPdfBytes(poderFile, 'Poder del representante'));
    }

    // 3. Adjuntos del aval
    componentes.push(await imageOrPdfToPdfBytes(avalIneFr, 'INE aval - frente'));
    componentes.push(await imageOrPdfToPdfBytes(avalIneRv, 'INE aval - reverso'));
    componentes.push(await imageOrPdfToPdfBytes(avalCompr, 'Comprobante de domicilio del aval'));

    // 4. Pagaré firmado físicamente (escaneado)
    componentes.push(await imageOrPdfToPdfBytes(pagareFirmadoFile, 'Pagaré firmado físicamente'));

    const final = await mergePDFs(componentes);
    const fname = `SolicitudCredito_${state.cliente.n}_${generarFechaArchivoCredito()}.pdf`;
    descargarPDF(final, fname);

    // Guardar snapshot de los datos del crédito al momento de la solicitud.
    // Si el cliente luego clickea "Finalizar pre-pedido", el XLS incluirá
    // automáticamente la sección "SOLICITUD DE EXTENSIÓN DE CRÉDITO".
    const _lc = state.cliente.lc || 0;
    const _sa = state.cliente.sa || 0;
    const _disp = Math.max(0, _lc - _sa);
    const _tot = creditoCalcularTotal();
    state.creditoSolicitado = {
      fechaSolicitud: new Date().toISOString(),
      lineaActual: _lc,
      saldoActual: _sa,
      creditoDisponible: _disp,
      totalPedido: _tot,
      nuevaLinea: calcularNuevaLineaSugerida(_lc, _sa, _tot),
    };

    // Cerrar modal y mostrar mensaje de confirmación
    closeModal();
    const correoAg = (state.agente && state.agente.mail) ? state.agente.mail : '—';
    const msgFinal = `
      <p>✓ Tu solicitud se descargó como <strong>${fname}</strong>.</p>
      <div class="credit-highlight-box" style="margin-top:14px">
        Envíala por correo a <a href="mailto:adgomez@padcolor.com"><strong>adgomez@padcolor.com</strong></a>
        con copia a <a href="mailto:jlogistica@padcolor.com"><strong>jlogistica@padcolor.com</strong></a>
        y a tu ejecutivo de ventas: <a href="mailto:${correoAg}"><strong>${correoAg}</strong></a>.
      </div>
      <p style="margin-top:14px">Gracias por tu solicitud, con estos documentos tramitamos tu extensión de crédito. Te haremos llegar una guía para que mandes Pagaré en original.</p>
    `;
    setTimeout(() => showModal('✓ Solicitud generada', msgFinal), 200);

  } catch(e){
    console.error(e);
    errEl.textContent = 'Error al generar la solicitud: ' + e.message;
    btn.textContent = txtOriginal;
    btn.disabled = false;
  }
}

async function generarCaratulaPDF(info){
  const { PDFDocument, rgb } = PDFLib;
  const doc = await PDFDocument.create();
  const mbr = await prepMbr(doc);
  const { fn: font, fnB: fontBold } = mbr;
  const { W, MX, BODY_TOP, BODY_BTM } = MBR;
  const azul = rgb(0, 0.08, 0.63);
  const page = doc.addPage([W, MBR.H]);
  drawMbr(page, mbr);

  let y = BODY_TOP - 10;
  page.drawText('SOLICITUD DE EXTENSIÓN', {x: MX, y, font: fontBold, size: 16, color: azul});
  y -= 18;
  page.drawText('DE LÍNEA DE CRÉDITO', {x: MX, y, font: fontBold, size: 16, color: azul});
  y -= 14;
  page.drawText('Padcolor — Día de Muertos · Halloween 2026', {x: MX, y, font, size: 9, color: rgb(.4,.4,.4)});
  y -= 7;
  page.drawLine({start: {x: MX, y}, end: {x: W - MX, y}, thickness: 1.2, color: azul});
  y -= 18;

  const LABEL_X = MX, VAL_X = MX + 185, ROW_H = 19;
  const drawRow = (label, value) => {
    if(y < BODY_BTM + 4) return;
    page.drawText(label, {x: LABEL_X, y, font: fontBold, size: 9, color: rgb(.35,.35,.35)});
    const wrapped = wordWrap(String(value), font, 10, (W - MX) - VAL_X);
    for(let i = 0; i < wrapped.length; i++){
      if(y < BODY_BTM + 4) break;
      page.drawText(wrapped[i], {x: VAL_X, y, font, size: 10});
      if(i < wrapped.length - 1) y -= 13;
    }
    y -= ROW_H;
  };

  drawRow('Fecha de solicitud:', new Date().toLocaleDateString('es-MX'));
  drawRow('Número de cliente:', state.cliente.n);
  drawRow('Tipo de persona:', state.tipoPersona === 'fisica' ? 'Persona Física' : 'Persona Moral');
  drawRow('Nombre / Razón social:', info.razonSocial);
  drawRow('RFC:', ($('cli-rfc').value || state.cliente.rfc || '').toUpperCase());
  drawRow('Solicitante (firmante):', info.solNombreCompleto);
  drawRow('Correo del firmante:', info.solEmail);
  drawRow('Teléfono del firmante:', info.solTel);
  drawRow('Aval:', info.avalNombreCompleto);

  y -= 6;
  page.drawText('RESUMEN FINANCIERO', {x: MX, y, font: fontBold, size: 12, color: azul});
  y -= 6;
  page.drawLine({start: {x: MX, y}, end: {x: W - MX, y}, thickness: .5, color: rgb(.8,.8,.8)});
  y -= 15;

  const total = creditoCalcularTotal();
  const lc = state.cliente.lc || 0;
  const sa = state.cliente.sa || 0;
  const disp = Math.max(0, lc - sa);
  drawRow('Línea de crédito actual:', '$' + lc.toLocaleString('es-MX', {minimumFractionDigits: 2}));
  drawRow('Saldo actual:', '$' + sa.toLocaleString('es-MX', {minimumFractionDigits: 2}));
  drawRow('Crédito disponible:', '$' + disp.toLocaleString('es-MX', {minimumFractionDigits: 2}));
  drawRow('Total del pre-pedido:', '$' + total.toLocaleString('es-MX', {minimumFractionDigits: 2}));
  drawRow('Nueva línea sugerida:', '$' + calcularNuevaLineaSugerida(lc, sa, total).toLocaleString('es-MX', {minimumFractionDigits: 2}));

  y -= 6;
  page.drawText('PRODUCTOS DEL PRE-PEDIDO', {x: MX, y, font: fontBold, size: 12, color: azul});
  y -= 16;
  page.drawText('Código', {x: MX, y, font: fontBold, size: 9});
  page.drawText('Descripción', {x: MX + 110, y, font: fontBold, size: 9});
  page.drawText('Cant.', {x: W - MX - 110, y, font: fontBold, size: 9});
  page.drawText('Subtotal', {x: W - MX - 70, y, font: fontBold, size: 9});
  y -= 14;

  Object.values(state.carrito).forEach(({p, q}) => {
    if(y < BODY_BTM + 4) return;
    if(!tienePrecio(p)) return;
    const precioPq = getPrecioPaquete(p);
    const sub = q * precioPq * 1.16;
    page.drawText(p.c, {x: MX, y, font, size: 8});
    page.drawText((p.d||'').substring(0, 50), {x: MX + 110, y, font, size: 8});
    page.drawText(String(q), {x: W - MX - 110, y, font, size: 8});
    page.drawText('$' + sub.toLocaleString('es-MX', {minimumFractionDigits: 2}), {x: W - MX - 70, y, font, size: 8});
    y -= 12;
  });

  return await doc.save();
}

async function imageOrPdfToPdfBytes(file, titulo){
  const { PDFDocument, rgb } = PDFLib;
  const azul = rgb(0, 0.08, 0.63);
  const buf = await file.arrayBuffer();
  const { W, MX, BODY_TOP, BODY_BTM } = MBR;
  const bW = W - 2*MX;
  const bH = BODY_TOP - BODY_BTM - 20; // 20pt para el título

  const doc = await PDFDocument.create();
  const mbr = await prepMbr(doc);
  const { fnB: fontBold } = mbr;

  const isPdf = file.type === 'application/pdf' || /\.pdf$/i.test(file.name);

  if(isPdf){
    // Embebe cada página del PDF dentro del membrete
    const embedded = await doc.embedPdf(buf);
    let first = true;
    for(const ep of embedded){
      const pg = doc.addPage([W, MBR.H]);
      drawMbr(pg, mbr);
      if(first){
        pg.drawText(titulo, {x: MX, y: BODY_TOP - 2, font: fontBold, size: 10, color: azul});
        first = false;
      }
      const sc = Math.min(bW/ep.width, bH/ep.height, 1);
      const eW = ep.width*sc, eH = ep.height*sc;
      pg.drawPage(ep, {x: MX + (bW-eW)/2, y: BODY_BTM + (bH-eH)/2 + 4, width: eW, height: eH});
    }
  } else {
    const img = (file.type === 'image/png' || /\.png$/i.test(file.name))
      ? await doc.embedPng(buf)
      : await doc.embedJpg(buf);
    const pg = doc.addPage([W, MBR.H]);
    drawMbr(pg, mbr);
    pg.drawText(titulo, {x: MX, y: BODY_TOP - 2, font: fontBold, size: 10, color: azul});
    const sc = Math.min(bW/img.width, bH/img.height, 1);
    const iW = img.width*sc, iH = img.height*sc;
    pg.drawImage(img, {x: MX + (bW-iW)/2, y: BODY_BTM + (bH-iH)/2 + 4, width: iW, height: iH});
  }

  return await doc.save();
}

async function mergePDFs(arrayBuffers){
  const { PDFDocument } = PDFLib;
  const final = await PDFDocument.create();
  for(const buf of arrayBuffers){
    const doc = await PDFDocument.load(buf);
    const pages = await final.copyPages(doc, doc.getPageIndices());
    pages.forEach(p => final.addPage(p));
  }
  return await final.save();
}

// ===== Init =====
function init(){
  buildFilterUI();
  setupSearch();
  setupClienteForm();
  setupFinalizar();
  renderProductos();
  renderCarrito();
  actualizarHeaderSugerido();
  // Precarga la compra 2025 (para la columna "Pz 2025" del modal de revisión).
  cargarCompra2025();
  cargarCon2025();
}

// API global para handlers inline en carrito
window.__padcolor = {
  cartQty: cambiarQtyCarrito,
  cartRemove: eliminarDelCarrito,
};

// Esperar DOM listo
if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

})();

